  private static void assertCleanupFunctionGuards() throws SQLException {
    for (Map.Entry<String, Integer> cleanup : CLEANUP_FUNCTION_LIMITS.entrySet()) {
      String function = "schubert." + cleanup.getKey();
      assertEquals(
          "BACKUP_GATE",
          queryString(
              "schubert_batch",
              "select reason_code from " + function + "('" + UUID_1 + "','" + FIXED_TIME + "',1)"));
      assertSqlState(
          "schubert_batch", "22023", "select * from " + function + "(null,'" + FIXED_TIME + "',1)");
      assertSqlState(
          "schubert_batch", "22023", "select * from " + function + "('" + UUID_1 + "',null,1)");
      assertSqlState(
          "schubert_batch",
          "22023",
          "select * from " + function + "('" + UUID_1 + "','" + FIXED_TIME + "',0)");
      assertSqlState(
          "schubert_batch",
          "22023",
          "select * from "
              + function
              + "('"
              + UUID_1
              + "','"
              + FIXED_TIME
              + "',"
              + (cleanup.getValue() + 1)
              + ")");
    }
    try (Connection holder = connection(ADMIN)) {
      holder.setAutoCommit(false);
      execute(holder, "select pg_advisory_xact_lock(71419602)");
      for (String cleanup : CLEANUP_FUNCTION_LIMITS.keySet()) {
        assertEquals(
            "LOCK_BUSY",
            queryString(
                "schubert_batch",
                "select reason_code from schubert."
                    + cleanup
                    + "('"
                    + UUID_1
                    + "','"
                    + FIXED_TIME
                    + "',1)"));
      }
      holder.rollback();
    }
  }

