        + id
        + ",'"
        + message
        + "','"
        + C
        + "','"
        + destination
        + "','QWKREQ01','001',decode(repeat('57',320),'hex'),'SENT','"
        + TIME
        + "','"
        + TIME
        + "','"
        + TIME
        + "')";
