  @Test
  void unavailableAesProviderProducesTypedBoundedFailure() {
    Provider provider = Security.getProvider("SunJCE");
    int position = providerPosition("SunJCE");
    Security.removeProvider("SunJCE");
    try (ResponseSnapshotCodec codec = fixedCodec("k2", CURRENT_KEY, null, null)) {
      ResponseSnapshotException failure =
          assertThrows(ResponseSnapshotException.class, () -> codec.encrypt(IDENTITY, new byte[0]));
      assertEquals(ResponseSnapshotException.Reason.CRYPTO_UNAVAILABLE, failure.reason());
      assertEquals("response snapshot encryption is unavailable", failure.getMessage());
      assertFalse(failure.getMessage().contains("000102"));
    } finally {
      assertNotEquals(-1, position);
      Security.insertProviderAt(provider, position);
    }
  }

  private static ResponseSnapshotCodec fixedCodec(
      String currentVersion, byte[] currentKey, String previousVersion, byte[] previousKey) {
    return new ResponseSnapshotCodec(
        currentVersion, currentKey, previousVersion, previousKey, new FixedSecureRandom(NONCE));
  }

  private static void assertInvalidAad(
      ResponseSnapshotCodec codec,
      EncryptedResponseSnapshot snapshot,
      ResponseSnapshotIdentity changed) {
    assertReason(
        ResponseSnapshotException.Reason.SNAPSHOT_INVALID, () -> codec.decrypt(changed, snapshot));
  }

  private static void assertInvalidCompressed(ResponseSnapshotCodec codec, byte[] compressed)
      throws Exception {
    EncryptedResponseSnapshot snapshot =
        independentSnapshot("k2", CURRENT_KEY, IDENTITY, compressed);
    assertReason(
        ResponseSnapshotException.Reason.SNAPSHOT_INVALID, () -> codec.decrypt(IDENTITY, snapshot));
  }

  private static void assertInvalidEnvelope(ResponseSnapshotCodec codec, byte[] envelope) {
    assertReason(
        ResponseSnapshotException.Reason.SNAPSHOT_INVALID,
        () -> codec.decrypt(IDENTITY, new EncryptedResponseSnapshot("k2", envelope)));
  }

  private static void assertReason(
      ResponseSnapshotException.Reason expected, ThrowingOperation operation) {
    ResponseSnapshotException failure =
        assertThrows(ResponseSnapshotException.class, operation::run);
    assertEquals(expected, failure.reason());
    assertFalse(failure.getMessage().contains("public synthetic snapshot"));
  }

  private static EncryptedResponseSnapshot independentSnapshot(
      String version, byte[] key, ResponseSnapshotIdentity identity, byte[] compressed)
      throws Exception {
    return new EncryptedResponseSnapshot(
        version,
        storedCiphertext(version, key, NONCE, independentAad(identity, version), compressed));
  }

  private static byte[] storedCiphertext(
      String keyVersion, byte[] key, byte[] nonce, byte[] aad, byte[] compressed) throws Exception {
    Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
    cipher.init(
        Cipher.ENCRYPT_MODE, new SecretKeySpec(key, "AES"), new GCMParameterSpec(128, nonce));
    cipher.updateAAD(aad);
    byte[] encrypted = cipher.doFinal(compressed);
    byte[] keyId = keyVersion.getBytes(StandardCharsets.US_ASCII);
    return ByteBuffer.allocate(NKENC1.length + 2 + keyId.length + nonce.length + encrypted.length)
        .put(NKENC1)
        .put(FORMAT_VERSION)
        .put((byte) keyId.length)
        .put(keyId)
        .put(nonce)
        .put(encrypted)
        .array();
  }

  private static byte[] independentAad(ResponseSnapshotIdentity identity, String keyVersion) {
    byte[] purpose = "api-inbox-response".getBytes(StandardCharsets.US_ASCII);
    byte[] table = "schubert.request_inbox".getBytes(StandardCharsets.US_ASCII);
    byte[] messageId =
        ByteBuffer.allocate(16)
            .putLong(identity.requestMessageId().getMostSignificantBits())
            .putLong(identity.requestMessageId().getLeastSignificantBits())
            .array();
    byte[] format = new byte[] {FORMAT_VERSION};
    byte[] keyId = keyVersion.getBytes(StandardCharsets.US_ASCII);
    byte[] layout = identity.responseLayoutId().getBytes(StandardCharsets.US_ASCII);
    byte[] version = identity.responseVersion().getBytes(StandardCharsets.US_ASCII);
    byte[] owner =
        identity.ownerUserId().isPresent()
            ? ByteBuffer.allocate(Long.BYTES).putLong(identity.ownerUserId().getAsLong()).array()
            : new byte[0];
    ByteBuffer buffer =
        ByteBuffer.allocate(
            8 * Integer.BYTES
                + purpose.length
                + table.length
                + messageId.length
                + format.length
                + keyId.length
                + layout.length
                + version.length
                + owner.length);
    putLengthPrefixed(buffer, purpose);
    putLengthPrefixed(buffer, table);
    putLengthPrefixed(buffer, messageId);
    putLengthPrefixed(buffer, format);
    putLengthPrefixed(buffer, keyId);
    putLengthPrefixed(buffer, layout);
    putLengthPrefixed(buffer, version);
    putLengthPrefixed(buffer, owner);
    return buffer.array();
  }

  private static void putLengthPrefixed(ByteBuffer buffer, byte[] value) {
    buffer.putInt(value.length);
    buffer.put(value);
  }

  private static byte[] independentCompress(byte[] plaintext) throws Exception {
    return independentCompress(plaintext, null);
  }

  private static byte[] independentCompressWithDictionary(byte[] plaintext) throws Exception {
    return independentCompress(plaintext, new byte[] {9, 8, 7, 6});
  }

  private static byte[] independentCompress(byte[] plaintext, byte[] dictionary) throws Exception {
    ByteArrayOutputStream output = new ByteArrayOutputStream();
    Deflater deflater = new Deflater(3);
    try {
      if (dictionary != null) {
        deflater.setDictionary(dictionary);
      }
      try (DeflaterOutputStream stream = new DeflaterOutputStream(output, deflater)) {
        stream.write(plaintext);
      }
    } finally {
      deflater.end();
    }
    return output.toByteArray();
  }

  private static byte[] sequence(int start) {
    byte[] value = new byte[32];
    for (int index = 0; index < value.length; index++) {
      value[index] = (byte) (start + index);
    }
    return value;
  }

  private static int providerPosition(String name) {
    Provider[] providers = Security.getProviders();
    for (int index = 0; index < providers.length; index++) {
      if (providers[index].getName().equals(name)) {
        return index + 1;
      }
    }
    return -1;
  }

  @FunctionalInterface
  private interface ThrowingOperation {
    void run();
  }

  private static final class FixedSecureRandom extends SecureRandom {
    private static final long serialVersionUID = 1L;
    private final byte[] value;

    private FixedSecureRandom(byte[] value) {
      this.value = value.clone();
    }

    @Override
    public void nextBytes(byte[] bytes) {
      System.arraycopy(value, 0, bytes, 0, bytes.length);
    }
  }
}

package dev.codex.schubert.nk.api.logging;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;
import java.sql.Connection;
import java.sql.SQLException;
import java.time.Instant;
import java.util.List;
import java.util.UUID;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/** PT-IDEM-013 / PT-DB-011. SS324/332/341 independent retention and NULL regression. */
final class MessageStoreCleanupTest {
  private static final UUID RUN = UUID.fromString("00000000-0000-0000-0000-000000000031");
  private static final Instant CUTOFF = Instant.parse("2026-09-07T00:00:00Z");
  @TempDir static Path root;
  private static ApiLogDatabaseFixture database;

  @BeforeAll
  static void start() throws Exception {
    database = new ApiLogDatabaseFixture(root);
  }

  @AfterAll
  static void stop() throws Exception {
    if (database != null) database.stop();
  }

  @BeforeEach
  void reset() throws SQLException {
    try (var connection = database.admin();
        var statement = connection.createStatement()) {
      statement.executeUpdate("delete from schubert.request_inbox");
      statement.executeUpdate("delete from schubert.mq_outbox");
      statement.executeUpdate("delete from schubert_web_session.web_log_outbox");
      statement.executeUpdate("delete from schubert.batch_runs");
    }
  }

  @Test
  void cleanupNullLimitsAreAlwaysRejected() throws SQLException {
    for (String function :
        List.of("notifications", "questions", "sessions", "message_stores", "logs", "batch_runs")) {
      try (var connection = database.admin();
          var role = connection.createStatement()) {
        role.execute("set role schubert_batch");
        try (var statement =
            connection.prepareStatement(
                "select reason_code from schubert.maintenance_cleanup_" + function + "(?,?,?)")) {
          statement.setObject(1, RUN);
          statement.setObject(2, CUTOFF.atOffset(java.time.ZoneOffset.UTC));
          statement.setNull(3, java.sql.Types.INTEGER);
          var failure = assertThrows(SQLException.class, statement::executeQuery, function);
          assertEquals("22023", failure.getSQLState(), function);
        }
      }
    }
  }

  @Test
  void sentRowsYoungerThanSevenDaysMustRemain() throws SQLException {
    try (var connection = database.admin()) {
      backup(connection);
      outbox(connection, false, 1, "SENT", CUTOFF.minusSeconds(172800), null);
      outbox(connection, true, 2, "SENT", CUTOFF.minusSeconds(172800), null);
      assertEquals("0|0|0|OK", cleanup(connection, 1000));
      assertEquals(2, rows(connection));
    }
  }

  @Test
  void sevenDayAndLeaseBoundariesPreserveProtectedRows() throws SQLException {
    try (var connection = database.admin()) {
      backup(connection);
      for (boolean web : List.of(false, true)) {
        Instant boundary = CUTOFF.minusSeconds(604800);
        outbox(connection, web, 1, "SENT", boundary.minusNanos(1000), null);
        outbox(connection, web, 2, "SENT", boundary, null);
        outbox(connection, web, 3, "SENT", boundary.plusNanos(1000), null);
        outbox(connection, web, 4, "SENT", boundary.minusNanos(1000), CUTOFF.minusNanos(1000));
        outbox(connection, web, 5, "SENT", boundary.minusNanos(1000), CUTOFF);
        outbox(connection, web, 6, "SENT", boundary.minusNanos(1000), CUTOFF.plusNanos(1000));
        outbox(connection, web, 7, "PENDING", null, null);
        outbox(connection, web, 8, "ERROR", null, CUTOFF.minusNanos(1000));
      }
      assertEquals("4|4|0|OK", cleanup(connection, 1000));
      for (String table : List.of("schubert.mq_outbox", "schubert_web_session.web_log_outbox")) {
        try (var statement = connection.createStatement();
            var result = statement.executeQuery("select id from " + table + " order by id")) {
          var ids = new java.util.ArrayList<Long>();
          while (result.next()) {
            ids.add(result.getLong(1));
          }
          assertEquals(List.of(2L, 3L, 5L, 6L, 7L, 8L), ids);
        }
      }
      assertEquals("0|0|0|OK", cleanup(connection, 1000));
      assertEquals(12, rows(connection));
    }
  }

  @Test
  void chunkLimitRollbackAndLockedRowsAreSafe() throws SQLException {
    try (var connection = database.admin();
        var locked = database.admin()) {
      backup(connection);
      outbox(connection, false, 1, "SENT", CUTOFF.minusSeconds(604801), null);
      outbox(connection, false, 2, "SENT", CUTOFF.minusSeconds(604801), null);
      outbox(connection, true, 3, "SENT", CUTOFF.minusSeconds(604801), null);
      locked.setAutoCommit(false);
      try (var statement = locked.createStatement();
          var result =
              statement.executeQuery("select id from schubert.mq_outbox where id=1 for update")) {
        assertTrue(result.next());
        assertEquals(1L, result.getLong(1));
      }
      connection.setAutoCommit(false);
      assertEquals("1|1|0|OK", cleanup(connection, 1));
      assertEquals(2, rows(connection));
      connection.rollback();
      assertEquals(3, rows(connection));
      assertEquals("1|1|0|OK", cleanup(connection, 1));
      connection.commit();
      assertEquals("1|1|0|OK", cleanup(connection, 1));
      connection.commit();
      assertEquals("0|0|0|OK", cleanup(connection, 1));
      connection.commit();
      assertEquals(1, rows(connection));
      locked.rollback();
      assertEquals("1|1|0|OK", cleanup(connection, 1));
      connection.commit();
      assertEquals(0, rows(connection));
      assertEquals("0|0|0|OK", cleanup(connection, 1));
      connection.commit();
      connection.setAutoCommit(true);
      for (int invalid : new int[] {0, 1001}) {
        assertEquals(
            "22023",
            assertThrows(SQLException.class, () -> cleanup(connection, invalid)).getSQLState());
      }
    }
  }

  private static void backup(Connection connection) throws SQLException {
    try (var statement =
        connection.prepareStatement(
            "insert into schubert.batch_runs(run_id,business_date,step,attempt,started_at,ended_at,status) "
                + "values(?,'2026-09-07',?,1,?,?,'SUCCESS')")) {
      for (String step : List.of("BACKUP_DB", "BACKUP_CONFIG")) {
        statement.setObject(1, RUN);
        statement.setString(2, step);
        statement.setObject(3, CUTOFF.atOffset(java.time.ZoneOffset.UTC));
        statement.setObject(4, CUTOFF.atOffset(java.time.ZoneOffset.UTC));
        assertEquals(1, statement.executeUpdate());
      }
    }
  }

  private static void outbox(
      Connection connection, boolean web, long id, String status, Instant sent, Instant lease)
      throws SQLException {
    String table = web ? "schubert_web_session.web_log_outbox" : "schubert.mq_outbox";
    String columns = web ? "payload_ciphertext,key_version" : "body,destination";
    String values =
        web
            ? "decode(repeat('00',29),'hex'),'synthetic-key'"
            : "decode('00','hex'),'nk.async.work'";
    try (var statement =
        connection.prepareStatement(
            "insert into "
                + table
                + " (id,message_id,correlation_id,layout_id,layout_version,"
                + columns
                + ",status,next_attempt_at,created_at,sent_at,lease_owner,lease_until) values(?,?,?,?,'001',"
                + values
                + ",?,?,?,?,?,?)")) {
      statement.setLong(1, id);
      statement.setObject(2, new UUID(0, id));
      statement.setObject(3, new UUID(1, id));
      statement.setString(4, web ? "WLGEVT01" : "QWKREQ01");
      statement.setString(5, status);
      statement.setObject(6, CUTOFF.minusSeconds(864000).atOffset(java.time.ZoneOffset.UTC));
      statement.setObject(7, CUTOFF.minusSeconds(864000).atOffset(java.time.ZoneOffset.UTC));
      statement.setObject(8, sent == null ? null : sent.atOffset(java.time.ZoneOffset.UTC));
      statement.setString(9, lease == null ? null : "synthetic-worker");
      statement.setObject(10, lease == null ? null : lease.atOffset(java.time.ZoneOffset.UTC));
      assertEquals(1, statement.executeUpdate());
    }
  }

  private static String cleanup(Connection connection, int limit) throws SQLException {
    try (var role = connection.createStatement()) {
      role.execute("set role schubert_batch");
    }
    try (var statement =
        connection.prepareStatement(
            "select target_count,deleted_count,skipped_count,reason_code from schubert.maintenance_cleanup_message_stores(?,?,?)")) {
      statement.setObject(1, RUN);
      statement.setObject(2, CUTOFF.atOffset(java.time.ZoneOffset.UTC));
      statement.setInt(3, limit);
      try (var result = statement.executeQuery()) {
        assertTrue(result.next());
        return result.getLong(1)
            + "|"
            + result.getLong(2)
            + "|"
            + result.getLong(3)
            + "|"
            + result.getString(4);
      }
    } finally {
      try (var role = connection.createStatement()) {
        role.execute("reset role");
      }
    }
  }

  private static int rows(Connection connection) throws SQLException {
    try (var statement = connection.createStatement();
        var result =
            statement.executeQuery(
                "select (select count(*) from schubert.mq_outbox)+(select count(*) from schubert_web_session.web_log_outbox)")) {
      assertTrue(result.next());
      return result.getInt(1);
    }
  }
}

