          "nk.web.log",
          "WLGEVT01",
          CORRELATION_ID,
          10_000,
          0,
          Optional.empty(),
          webLogRoute);

      BytesMessage shortBody = bytes(context, new byte[255]);
      setRequestIdentity(shortBody, "LOGREQ01", new ActiveMQQueue("nk.sync.reply.web"));
      assertDecodeRejected(
          roundTrip(
              context,
              request.address(),
              shortBody,
              DeliveryMode.PERSISTENT,
              request.timeToLiveMillis()),
          route);

      BytesMessage nonPersistent = bytes(context, validBody);
      setRequestIdentity(nonPersistent, "LOGREQ01", new ActiveMQQueue("nk.sync.reply.web"));
      assertDecodeRejected(
          roundTrip(
              context,
              request.address(),
              nonPersistent,
              DeliveryMode.NON_PERSISTENT,
              request.timeToLiveMillis()),
          route);

      BytesMessage missingLayout = bytes(context, validBody);
      missingLayout.setJMSCorrelationID(MESSAGE_ID.toString());
      missingLayout.setJMSReplyTo(new ActiveMQQueue("nk.sync.reply.web"));
      missingLayout.setStringProperty("NKMessageID", MESSAGE_ID.toString());
      missingLayout.setStringProperty("NKProtocolVersion", "001");
      Message missingReceived =
          roundTrip(
              context,
              request.address(),
              missingLayout,
              DeliveryMode.PERSISTENT,
              request.timeToLiveMillis());
      assertThrows(PermanentProtocolException.class, () -> GUARD.read(missingReceived, route));

      BytesMessage unknownLayout = bytes(context, validBody);
      setRequestIdentity(unknownLayout, "ZZZREQ01", new ActiveMQQueue("nk.sync.reply.web"));
      assertDecodeRejected(
          roundTrip(
              context,
              request.address(),
              unknownLayout,
              DeliveryMode.PERSISTENT,
              request.timeToLiveMillis()),
          route);

      BytesMessage unknownProtocol = bytes(context, validBody);
      setRequestIdentity(unknownProtocol, "LOGREQ01", new ActiveMQQueue("nk.sync.reply.web"));
      unknownProtocol.setStringProperty("NKProtocolVersion", "999");
      assertDecodeRejected(
          roundTrip(
              context,
              request.address(),
              unknownProtocol,
              DeliveryMode.PERSISTENT,
              request.timeToLiveMillis()),
          route);

      BytesMessage dynamicReply = bytes(context, validBody);
      setRequestIdentity(dynamicReply, "LOGREQ01", new ActiveMQQueue("nk.unapproved.reply"));
      Message dynamicReceived =
          roundTrip(
              context,
              request.address(),
              dynamicReply,
              DeliveryMode.PERSISTENT,
              request.timeToLiveMillis());
      assertThrows(PermanentProtocolException.class, () -> GUARD.read(dynamicReceived, route));
    } finally {
      broker.stop();
    }
  }

  private static void assertDecodeRejected(Message received, ExpectedRoute route) throws Exception {
    GuardedJmsMessage guarded = GUARD.read(received, route);
    assertThrows(
        PermanentProtocolException.class,
        () -> FixedWidthDecoder.standard().decode(guarded.body(), guarded.metadata(), route));
  }

  private static void assertRouteBodyLimit(
      JMSContext context,
      String address,
      String layoutId,
      UUID correlationId,
      int maximumLength,
      long timeToLive,
      Optional<String> replyTo,
      ExpectedRoute route)
      throws Exception {
    BytesMessage maximum = bytes(context, new byte[maximumLength]);
    setIdentity(maximum, layoutId, correlationId);
    if (replyTo.isPresent()) {
      maximum.setJMSReplyTo(new ActiveMQQueue(replyTo.orElseThrow()));
    }
    GuardedJmsMessage accepted =
        guardRoundTrip(context, address, maximum, DeliveryMode.PERSISTENT, timeToLive, route);
    assertEquals(maximumLength, accepted.body().length);

    BytesMessage excessive = bytes(context, new byte[maximumLength + 1]);
    setIdentity(excessive, layoutId, correlationId);
    if (replyTo.isPresent()) {
      excessive.setJMSReplyTo(new ActiveMQQueue(replyTo.orElseThrow()));
    }
    assertThrows(
        PermanentProtocolException.class,
        () ->
            guardRoundTrip(
                context, address, excessive, DeliveryMode.PERSISTENT, timeToLive, route));
  }

  private static Message roundTrip(
      JMSContext context, String address, Message outbound, int deliveryMode, long timeToLive)
      throws JMSException {
    Queue destination = new ActiveMQQueue(address + "::" + address + ".q");
    try (JMSConsumer consumer = context.createConsumer(destination)) {
      context
          .createProducer()
          .setDeliveryMode(deliveryMode)
          .setTimeToLive(timeToLive)
          .send(destination, outbound);
      Message received = consumer.receive(10_000);
      assertNotNull(received);
      return received;
    }
  }

  private static GuardedJmsMessage guardRoundTrip(
      JMSContext context,
      String address,
      Message outbound,
      int deliveryMode,
      long timeToLive,
      ExpectedRoute route)
      throws JMSException {
    Queue destination = new ActiveMQQueue(address + "::" + address + ".q");
    try (JMSConsumer consumer = context.createConsumer(destination)) {
      context
          .createProducer()
          .setDeliveryMode(deliveryMode)
          .setTimeToLive(timeToLive)
          .send(destination, outbound);
      Message received = consumer.receive(10_000);
      assertNotNull(received);
      return GUARD.read(received, route);
    }
  }

  private static BytesMessage bytes(JMSContext context, byte[] body) throws JMSException {
    BytesMessage message = context.createBytesMessage();
    message.writeBytes(body);
    return message;
  }

  private static void setRequestIdentity(Message message, String layoutId, Queue replyTo)
      throws JMSException {
    setIdentity(message, layoutId, MESSAGE_ID);
    message.setJMSReplyTo(replyTo);
  }

  private static void setIdentity(Message message, String layoutId, UUID correlationId)
      throws JMSException {
    message.setJMSCorrelationID(correlationId.toString());
    message.setStringProperty("NKMessageID", MESSAGE_ID.toString());
    message.setStringProperty("NKLayoutID", layoutId);
    message.setStringProperty("NKProtocolVersion", "001");
  }

  private static void setReplyTo(Message message, Queue replyTo) {
    try {
      message.setJMSReplyTo(replyTo);
    } catch (JMSException exception) {
      throw new IllegalStateException("synthetic reply-to could not be set", exception);
    }
  }

  private static byte[] independentWire(RouteVector vector) {
    int totalLength = 256 + vector.dataLength();
    byte[] body = new byte[totalLength];
    Arrays.fill(body, (byte) ' ');
    ascii(body, 0, "SCHBNK01");
    ascii(body, 8, "001");
    ascii(body, 11, vector.layoutId());
    ascii(body, 19, "001");
    body[22] = (byte) vector.messageKindWire();
    body[23] = (byte) vector.interactionKindWire();
    ascii(body, 24, MESSAGE_ID.toString());
    ascii(body, 60, vector.correlationId().toString());
    ascii(body, 96, "20260903120000000");
    if (vector.messageKind() != MessageKind.EVENT) {
      ascii(body, 113, "a".repeat(64));
    }
    ascii(body, 177, "0256");
    ascii(body, 181, sixDigits(vector.dataLength()));
    ascii(body, 187, "000000");
    ascii(body, 193, "000000");
    ascii(body, 199, nineDigits(totalLength));
    if (vector.messageKind() == MessageKind.RESPONSE) {
      ascii(body, 208, "0000");
    }
    return body;
  }

  private static String sixDigits(int value) {
    return String.format(Locale.ROOT, "%06d", value);
  }

  private static String nineDigits(int value) {
    return String.format(Locale.ROOT, "%09d", value);
  }

  private static void ascii(byte[] target, int offset, String value) {
    byte[] source = value.getBytes(StandardCharsets.US_ASCII);
    System.arraycopy(source, 0, target, offset, source.length);
  }

  private static EmbeddedActiveMQ start(Path root) throws Exception {
    Path template = Path.of(System.getProperty("broker.template"));
    Configuration configuration;
    try (InputStream input = Files.newInputStream(template)) {
      configuration = new FileConfigurationParser().parseMainConfig(input);
    }
    configuration
        .setPagingDirectory(root.resolve("paging").toString())
        .setBindingsDirectory(root.resolve("bindings").toString())
        .setJournalDirectory(root.resolve("journal").toString())
        .setLargeMessagesDirectory(root.resolve("large-messages").toString())
        .setSecurityEnabled(false)
        .clearAcceptorConfigurations()
        .addAcceptorConfiguration("component", "vm://0");
    return new EmbeddedActiveMQ().setConfiguration(configuration).start();
  }

  private record RouteVector(
      String address,
      String layoutId,
      MessageKind messageKind,
      InteractionKind interactionKind,
      char messageKindWire,
      char interactionKindWire,
      int dataLength,
      long timeToLiveMillis,
      Optional<String> replyTo) {

    private UUID correlationId() {
      return messageKind == MessageKind.REQUEST ? MESSAGE_ID : CORRELATION_ID;
    }

    private ExpectedRoute expectedRoute() {
      return new ExpectedRoute(
          messageKind, interactionKind, address, replyTo, timeToLiveMillis > 0);
    }
  }
}

package dev.codex.schubert.nk.api.messaging.inbound;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

import jakarta.jms.JMSConsumer;
import jakarta.jms.JMSContext;
import jakarta.jms.Message;
import jakarta.jms.MessageListener;
import java.lang.reflect.Proxy;
import java.time.Clock;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.BooleanSupplier;
import java.util.function.Supplier;
import org.junit.jupiter.api.Test;

/** SSC314/BUG1548/YKT1307; PT-API-JMS-CLOSE001..006; finite owned proxies, no broker. */
final class ApiConsumerCloseOwnershipTest {
  @Test
  void close001OnlyUnconfirmedContextIsRetriedAcrossAllThreeConsumers() throws Exception {
    for (int kind = 0; kind < 3; kind++) {
      int count = kind == 0 ? 4 : 1;
      for (int bad = 0; bad < count; bad++) {
        for (Throwable marker :
            List.of(new IllegalStateException("fixture"), new AssertionError("fixture"))) {
          var contexts = fixtures(count, bad, marker, false);
          var index = new AtomicInteger();
          var owner = open(kind, () -> contexts.get(index.getAndIncrement()).context);
          assertTrue(ready(owner));
          Class<? extends Throwable> expectedType =
              marker instanceof Error ? Error.class : IllegalStateException.class;
          var failure = assertThrows(expectedType, owner::close);
          if (marker instanceof Error) assertSame(marker, failure);
          else assertSame(marker, failure.getCause());
          assertFalse(ready(owner));
          assertCounts(contexts, bad, 1, 1);
          owner.close();
          assertCounts(contexts, bad, 2, 1);
          owner.close();
          assertCounts(contexts, bad, 2, 1);
        }
      }
    }
  }

  @Test
  void close002ConcurrentConsumerCloseNeverDuplicatesConfirmedWork() throws Exception {
    for (int kind = 0; kind < 3; kind++) {
      var contexts = fixtures(kind == 0 ? 4 : 1, 0, null, true);
      var index = new AtomicInteger();
      var owner = open(kind, () -> contexts.get(index.getAndIncrement()).context);
      concurrent(owner, contexts.getFirst());
      assertCounts(contexts, 0, 1, 1);
      assertFalse(ready(owner));
      owner.close();
      assertCounts(contexts, 0, 1, 1);
    }
  }

  @Test
  void close003StoppedConsumersDoNotInspectOrProcessAnotherDelivery() throws Exception {
    for (int kind = 0; kind < 3; kind++) {
      var contexts = fixtures(kind == 0 ? 4 : 1, 0, new IllegalStateException("fixture"), false);
      var index = new AtomicInteger();
      var owner = open(kind, () -> contexts.get(index.getAndIncrement()).context);
      assertThrows(IllegalStateException.class, owner::close);
      var touched = new AtomicInteger();
      var message =
          (Message)
              Proxy.newProxyInstance(
                  Message.class.getClassLoader(),
                  new Class<?>[] {Message.class},
                  (ignored, method, arguments) -> {
                    touched.incrementAndGet();
                    throw new AssertionError("delivery after stop");
                  });
      for (var fixture : contexts) fixture.listener.get().onMessage(message);
      assertEquals(0, touched.get());
      owner.close();
    }
  }

  @Test
  void close004ParentRetainsOnlyUnknownChildAcrossReverseGroupClose() throws Exception {
    for (int bad = 0; bad < 6; bad++) {
      for (Throwable marker :
          List.of(new IllegalStateException("fixture"), new AssertionError("fixture"))) {
        var contexts = fixtures(6, bad, marker, false);
        var order = new ArrayList<Integer>();
        for (int i = 0; i < 6; i++) {
          contexts.get(i).order = order;
          contexts.get(i).ordinal = i;
        }
        var runtime = parent(contexts);
        assertTrue(runtime.ready());
        Class<? extends Throwable> expectedType =
            marker instanceof Error ? Error.class : IllegalStateException.class;
        var failure = assertThrows(expectedType, runtime::close);
        if (marker instanceof Error) assertSame(marker, failure);
        assertEquals(List.of(5, 4, 0, 1, 2, 3), order);
        assertFalse(runtime.ready());
        runtime.close();
        assertCounts(contexts, bad, 2, 1);
        assertEquals(bad, order.getLast());
        runtime.close();
        assertCounts(contexts, bad, 2, 1);
        assertEquals(7, order.size());
      }
    }
  }

  @Test
  void close005ConcurrentParentRetainsSingleCloseSequence() throws Exception {
    var contexts = fixtures(6, 5, null, true);
    var runtime = parent(contexts);
    concurrent(runtime, contexts.getLast());
    assertCounts(contexts, 0, 1, 1);
    assertFalse(runtime.ready());
  }

  @Test
  void close006PersistentUnknownNeverBecomesSuccessfulNoOp() {
    var marker = new AssertionError("fixture persistent");
    var contexts = fixtures(6, 0, marker, false);
    contexts.getFirst().persistent = true;
    var runtime = parent(contexts);
    assertSame(marker, assertThrows(AssertionError.class, runtime::close));
    assertSame(marker, assertThrows(AssertionError.class, runtime::close));
    assertCounts(contexts, 0, 2, 1);
    assertFalse(runtime.ready());
    contexts.getFirst().persistent = false;
    runtime.close();
    assertCounts(contexts, 0, 3, 1);
  }

  private static ApiMessagingRuntime parent(List<Context> contexts) {
    var index = new AtomicInteger();
    Supplier<JMSContext> factory = () -> contexts.get(index.getAndIncrement()).context;
    return ApiMessagingRuntime.start(
        factory,
        factory,
        factory,
        ignored -> new byte[0],
        ignored -> {},
        ignored -> {},
        Clock.systemUTC(),
        ignored -> fail("unexpected terminal"),
        () -> fail("unexpected fatal"));
  }

  private static AutoCloseable open(int kind, Supplier<JMSContext> factory) {
    return switch (kind) {
      case 0 ->
          SyncRequestConsumers.start(
              factory,
              new SyncRequestListener(
                  ignored -> {
                    throw new AssertionError("unexpected processor");
                  },
                  Clock.systemUTC()),
              ignored -> fail("unexpected terminal"));
      case 1 ->
          WebLogConsumers.start(
              factory,
              new WebLogListener(ignored -> fail("unexpected processor"), Clock.systemUTC()),
              ignored -> fail("unexpected terminal"));
      case 2 ->
          QuestionWorkConsumers.start(
              factory,
              new QuestionWorkListener(ignored -> fail("unexpected processor"), Clock.systemUTC()),
              ignored -> fail("unexpected terminal"),
              () -> fail("unexpected fatal"));
      default -> throw new AssertionError("fixture kind");
    };
  }

  private static boolean ready(AutoCloseable owner) {
    if (owner instanceof SyncRequestConsumers sync) return sync.ready();
    if (owner instanceof WebLogConsumers log) return log.ready();
    if (owner instanceof QuestionWorkConsumers question) return question.ready();
    return ((ApiMessagingRuntime) owner).ready();
  }

  private static List<Context> fixtures(int count, int bad, Throwable failure, boolean hold) {
    var result = new ArrayList<Context>();
    for (int i = 0; i < count; i++)
      result.add(
          new Context(
              i == bad ? Optional.ofNullable(failure) : Optional.empty(), hold && i == bad));
    return result;
  }

  private static void assertCounts(List<Context> contexts, int bad, int retried, int confirmed) {
    for (int i = 0; i < contexts.size(); i++)
      assertEquals(i == bad ? retried : confirmed, contexts.get(i).closes.get(), "child " + i);
  }

  private static void concurrent(AutoCloseable owner, Context gate) throws Exception {
    var firstFailure = new AtomicReference<Throwable>();
    var secondFailure = new AtomicReference<Throwable>();
    var first = new Thread(() -> observedClose(owner, firstFailure));
    var second = new Thread(() -> observedClose(owner, secondFailure));
    first.start();
    try {
      assertTrue(gate.entered.await(5, TimeUnit.SECONDS));
      assertFalse(ready(owner));
      second.start();
      // SS314 requires blocked serialization, not one specific private lock implementation.
      await(
          () ->
              second.getState() == Thread.State.WAITING
                  || second.getState() == Thread.State.BLOCKED);
      assertEquals(1, gate.closes.get());
    } finally {
      gate.release.countDown();
      try {
        first.join(5000);
      } finally {
        second.join(5000);
      }
    }
    assertFalse(first.isAlive());
    assertFalse(second.isAlive());
    assertNull(firstFailure.get());
    assertNull(secondFailure.get());
  }

  private static void observedClose(AutoCloseable owner, AtomicReference<Throwable> failure) {
    try {
      owner.close();
    } catch (Throwable outcome) {
      failure.set(outcome);
    }
  }

  private static void await(BooleanSupplier condition) throws InterruptedException {
    long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
    while (!condition.getAsBoolean() && System.nanoTime() - deadline < 0) Thread.sleep(1);
    assertTrue(condition.getAsBoolean());
  }

  private static final class Context {
    final AtomicInteger closes = new AtomicInteger();
    final AtomicReference<MessageListener> listener = new AtomicReference<>();
    final CountDownLatch entered = new CountDownLatch(1);
    final CountDownLatch release;
    final Optional<Throwable> failure;
    final JMSContext context;
    boolean persistent;
    List<Integer> order = new ArrayList<>();
    int ordinal;

    Context(Optional<Throwable> failure, boolean hold) {
      this.failure = failure;
      release = new CountDownLatch(hold ? 1 : 0);
      var consumer =
          (JMSConsumer)
              Proxy.newProxyInstance(
                  JMSConsumer.class.getClassLoader(),
                  new Class<?>[] {JMSConsumer.class},
                  (ignored, method, arguments) -> {
                    if (method.getName().equals("setMessageListener")) {
                      listener.set((MessageListener) arguments[0]);
                      return null;
                    }
                    throw new AssertionError(method.getName());
                  });
      context =
          (JMSContext)
              Proxy.newProxyInstance(
                  JMSContext.class.getClassLoader(),
                  new Class<?>[] {JMSContext.class},
                  (ignored, method, arguments) ->
                      switch (method.getName()) {
                        case "setAutoStart", "start" -> null;
                        case "getSessionMode" -> JMSContext.SESSION_TRANSACTED;
                        case "createConsumer" -> consumer;
                        case "close" -> {
                          int attempt = closes.incrementAndGet();
                          order.add(ordinal);
                          entered.countDown();
                          if (!release.await(5, TimeUnit.SECONDS))
                            throw new AssertionError("fixture gate expired");
                          if (failure.isPresent() && (attempt == 1 || persistent))
                            throw failure.orElseThrow();
                          yield null;
                        }
                        default -> throw new AssertionError(method.getName());
                      });
    }
  }
}

package dev.codex.schubert.nk.api.messaging.inbound;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

import jakarta.jms.JMSContext;
import java.lang.reflect.Proxy;
import java.time.Clock;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;
import org.junit.jupiter.api.Test;

/** PT-OPS-API-REM001..003: independent provider identity/order, not native acceptance. */
class ApiConsumerRemainderTest {
  @Test
  void factoryFailureSignalsBeforeClosingAllEarlierOwnersWithFatalPriority() {
    for (boolean primaryFatal : List.of(false, true)) {
      for (int notificationKind = 0; notificationKind < 4; notificationKind++) {
        for (int cleanupKind = 0; cleanupKind < 4; cleanupKind++) {
          Throwable primary =
              primaryFatal ? new AssertionError("primary") : new IllegalStateException("primary");
          Throwable notification =
              switch (notificationKind) {
                case 1 -> primary;
                case 2 -> new IllegalStateException("notification");
                case 3 -> new AssertionError("notification");
                default -> null;
              };
          Throwable cleanup =
              switch (cleanupKind) {
                case 1 -> new IllegalStateException("cleanup");
                case 2 -> new AssertionError("cleanup");
                case 3 -> primary;
                default -> null;
              };
          var calls = new ArrayList<String>();
          var index = new AtomicInteger();
          Supplier<JMSContext> sync = () -> context(index.incrementAndGet(), calls, cleanup);
          Supplier<JMSContext> failed =
              () -> {
                raise(primary);
                throw new AssertionError("unreachable fixture");
              };
          Throwable selected =
              notification instanceof Error && !primaryFatal ? notification : primary;
          Throwable expected =
              cleanup instanceof Error && !(selected instanceof Error) ? cleanup : selected;
          Class<? extends Throwable> expectedType =
              expected instanceof Error ? AssertionError.class : IllegalStateException.class;
          var actual =
              assertThrows(
                  expectedType,
                  () ->
                      ApiMessagingRuntime.start(
                          sync,
                          failed,
                          sync,
                          ignored -> new byte[0],
                          ignored -> {},
                          ignored -> {},
                          Clock.systemUTC(),
                          ignored -> fail("no delivery"),
                          () -> {
                            calls.add("signal");
                            raise(notification);
                          }));
          assertSame(expected, expected instanceof Error ? actual : actual.getCause());
          assertEquals(List.of("signal", "close1", "close2", "close3", "close4"), calls);
          assertEquals(4, index.get());
          if (selected != primary) assertSame(primary, selected.getSuppressed()[0]);
          if (notification != null && notification != primary && selected == primary)
            assertSame(notification, primary.getSuppressed()[0]);
        }
      }
    }
  }

  @Test
  void syncDrainPromotesLaterErrorButAttemptsAllFourContexts() {
    var closes = new AtomicInteger();
    var opened = new AtomicInteger();
    var fatal = new AssertionError("later close fatal");
    var owner =
        SyncRequestConsumers.start(
            () ->
                QuestionWorkConsumersTest.context(
                    "",
                    null,
                    opened.incrementAndGet() == 1
                        ? new IllegalStateException("first close")
                        : fatal,
                    closes),
            new SyncRequestListener(ignored -> new byte[0], Clock.systemUTC()),
            ignored -> {},
            () -> {});
    assertSame(fatal, assertThrows(AssertionError.class, owner::close));
    assertEquals(4, closes.get());
    assertEquals(0, fatal.getSuppressed().length);
    assertSame(fatal, assertThrows(AssertionError.class, owner::close));
    assertFalse(owner.ready());
    assertEquals(8, closes.get());
  }

  @Test
  void completeProfileClosesInReverseGroupOrderAndPreservesDistinctFatalIdentity() {
    for (int kind = 0; kind < 5; kind++) {
      var calls = new ArrayList<String>();
      var index = new AtomicInteger();
      var firstFatal = new AssertionError("first fatal");
      var laterFatal = new AssertionError("later fatal");
      Throwable[] faults = new Throwable[6];
      switch (kind) {
        case 1 -> {
          faults[5] = firstFatal;
          faults[4] = laterFatal;
        }
        case 2 -> {
          faults[5] = new IllegalStateException("question close");
          faults[4] = firstFatal;
        }
        case 3 -> {
          faults[5] = firstFatal;
          faults[0] = firstFatal;
        }
        case 4 -> {
          faults[5] = firstFatal;
          faults[4] = firstFatal;
        }
        default -> {}
      }
      Supplier<JMSContext> factory =
          () -> {
            int n = index.incrementAndGet();
            return context(n, calls, faults[n - 1]);
          };
      var runtime =
          ApiMessagingRuntime.start(
              factory,
              factory,
              factory,
              ignored -> new byte[0],
              ignored -> {},
              ignored -> {},
              Clock.systemUTC(),
              ignored -> fail("no delivery"),
              () -> fail("no fatal signal"));
      assertTrue(runtime.ready());
      assertFalse(runtime.terminalFailureObserved());
      if (kind == 0) runtime.close();
      else assertSame(firstFatal, assertThrows(AssertionError.class, runtime::close));
      assertEquals(List.of("close6", "close5", "close1", "close2", "close3", "close4"), calls);
      assertEquals(kind == 1 ? 1 : 0, firstFatal.getSuppressed().length);
      if (kind == 1) assertSame(laterFatal, firstFatal.getSuppressed()[0]);
      if (kind == 0) {
        runtime.close();
        assertEquals(6, calls.size());
      } else {
        assertSame(firstFatal, assertThrows(AssertionError.class, runtime::close));
        // Successful children never run again; only the two faulting contexts remain unknown.
        assertEquals(8, calls.size());
        assertEquals(
            kind == 3 ? List.of("close6", "close1") : List.of("close6", "close5"),
            calls.subList(6, 8));
      }
      assertFalse(runtime.ready());
    }
  }

  @Test
  void partialConsumerCleanupFatalAndSameIdentityAreNeverNormalSuccess() {
    for (boolean webLog : List.of(false, true)) {
      for (boolean primaryFatal : List.of(false, true)) {
        for (boolean same : List.of(false, true)) {
          Throwable primary =
              primaryFatal ? new AssertionError("startup") : new IllegalStateException("startup");
          Throwable closing = same ? primary : new AssertionError("close");
          var count = new AtomicInteger();
          var stopped = new AtomicInteger();
          Supplier<JMSContext> source =
              () -> {
                var delegate = QuestionWorkConsumersTest.context("start", primary, closing, count);
                return (JMSContext)
                    Proxy.newProxyInstance(
                        JMSContext.class.getClassLoader(),
                        new Class<?>[] {JMSContext.class},
                        (p, m, a) -> {
                          if (m.getName().equals("close")) assertEquals(1, stopped.get());
                          return QuestionWorkConsumersTest.invoke(delegate, m, a);
                        });
              };
          Class<? extends Throwable> expectedType =
              primaryFatal || !same ? AssertionError.class : IllegalStateException.class;
          var actual =
              assertThrows(
                  expectedType,
                  () -> {
                    if (webLog)
                      WebLogConsumers.start(
                          source,
                          new WebLogListener(ignored -> {}, Clock.systemUTC()),
                          ignored -> {},
                          stopped::incrementAndGet);
                    else
                      SyncRequestConsumers.start(
                          source,
                          new SyncRequestListener(ignored -> new byte[0], Clock.systemUTC()),
                          ignored -> {},
                          stopped::incrementAndGet);
                  });
          if (primaryFatal) assertSame(primary, actual);
          else if (!same) assertSame(closing, actual);
          else assertSame(primary, actual.getCause());
          assertEquals(webLog ? 1 : 4, count.get());
          assertEquals(1, stopped.get());
          assertFalse(List.of(primary.getSuppressed()).contains(primary));
        }
      }
    }
  }

  private static JMSContext context(int number, List<String> calls, Throwable close) {
    var delegate = QuestionWorkConsumersTest.context("", null, close, new AtomicInteger());
    return (JMSContext)
        Proxy.newProxyInstance(
            JMSContext.class.getClassLoader(),
            new Class<?>[] {JMSContext.class},
            (p, m, a) -> {
              if (m.getName().equals("close")) calls.add("close" + number);
              return QuestionWorkConsumersTest.invoke(delegate, m, a);
            });
  }

  private static void raise(Throwable failure) {
    if (failure instanceof RuntimeException runtime) throw runtime;
    if (failure instanceof Error fatal) throw fatal;
  }
}

