  private static void goldenFinal(BackupPublicationFixture f)
      throws IOException, NoSuchAlgorithmException {
    assertArrayEquals(
        BackupArtifactFixture.golden(),
        Files.readAllBytes(finalDirectory(f).resolve("MANIFEST.json")));
