                case "mode" -> List.of(0, 0120777, 0140600, 0100666, 040777);
                case "nlink" -> role.equals("dir") ? List.of(0, 1) : List.of(0, 2);
                case "size" ->
                    role.equals("dir") ? List.of(-1L) : List.of(-1L, 0L, runtime ? 111L : 65849L);
