  }

  @Test
  void main455003InvalidOrMissingArgsNeverEnterCompletion() {
    for (String[] args :
        List.of(
            new String[] {"x"},
            new String[] {"--resume"},
            new String[] {"--resume", "00000000-0000-0000-0000-000000000000"},
            new String[] {"--resume", "invalid"},
