            Instant.parse("2026-09-13T02:02:01Z"),
            reason.code(),
            reason.summary());
    return new MorningDatabaseSession.ExpiryObservation(
        f.expiry().begins(),
        Instant.parse("2026-09-13T02:02:01Z"),
        result,
        audit,
        ExpiryReceiptFixture.receipt(code, "d".repeat(32)));
