    var expiry =
        new MorningDatabaseSession.ExpiryObservation(
            new MorningDatabaseSession.ExpiryBegins(
                onRun(old.begins().current(), foreign), Optional.empty()),
            old.ended(),
            old.result(),
            old.audit(),
            old.receipt());
