                          new BatchStepAttempt(2, run, BatchStep.BACKUP_CONFIG, 1, now, false));
                    }

                    public <T> T handoffCleanup(MorningDatabaseSession.CleanupHandoff<T> work) {
                      return fail("cleanup outside this test");
