    assertTrue(events.indexOf("INVALID") < events.indexOf("backup-begin"));
    assertTrue(events.indexOf("backup-begin") < events.indexOf("DB-original-close"));
    assertFalse(m.held.get() || a.held.get() || dbHeld.get());
  }

