  @Test
  void issRel002MalformedHashesMapsAndArtifactPathsAreRejected() {
    var good = facts("PUBLIC", artifacts());
    var contents = good.contents();
    for (String wrong : List.of("", "a".repeat(63), "A".repeat(64), "g".repeat(64))) {
