package dev.codex.schubert.nk.batch.file;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

import dev.codex.schubert.nk.storage.LinuxFileLock;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicBoolean;
import org.junit.jupiter.api.Test;

/** NK-OPS-001/OPS009/UI251/SS341/343/PG336; PT-OPS-MROOT001-006. */
final class MorningRootScopeTest {
  private static final class Held implements MorningRootScope.Exclusive {
    private final List<String> order;
    private final AtomicBoolean held;
    private boolean available = true;

    Held(List<String> order, AtomicBoolean held) {
      this.order = order;
      this.held = held;
    }

    @Override
    public <T> Optional<T> execute(LinuxFileLock.Operation<T> operation) throws IOException {
      order.add("M-enter");
      if (!available) return Optional.empty();
      held.set(true);
      try {
        return Optional.of(operation.execute());
      } finally {
        held.set(false);
        order.add("M-close");
      }
    }
  }

  @Test
  void mroot001RetainsRealOrderAndMThroughContinuation() throws Exception {
    var order = new ArrayList<String>();
    var held = new AtomicBoolean();
    var lock = new Held(order, held);
    var result =
        MorningRootScope.execute(
            () -> order.add("root"),
            lock,
            () -> {
              assertTrue(held.get());
              order.add("all-eight-policy");
            },
            () -> {
              assertTrue(held.get());
              order.add("trusted-continuation");
              return 7;
            });
    assertEquals(7, result);
    assertFalse(held.get());
    assertEquals(
        List.of(
            "root",
            "M-enter",
            "root",
            "all-eight-policy",
            "root",
            "trusted-continuation",
            "root",
            "M-close",
            "root"),
        order);
  }

  @Test
  void mroot002BusyMNeverInspectsUnitsOrContinues() {
    var order = new ArrayList<String>();
    var held = new AtomicBoolean();
    var lock = new Held(order, held);
    lock.available = false;
    assertThrows(
        IOException.class,
        () ->
            MorningRootScope.execute(
                () -> order.add("root"),
                lock,
                () -> fail("no policy on M contention"),
                () -> fail("no continuation on M contention")));
    assertEquals(List.of("root", "M-enter"), order);
    assertFalse(held.get());
  }

  @Test
  void mroot003PolicyRefusalNeverContinuesAndClosesM() {
    var order = new ArrayList<String>();
    var held = new AtomicBoolean();
    var failure = new IOException("fixed policy unavailable");
    assertSame(
        failure,
        assertThrows(
            IOException.class,
            () ->
                MorningRootScope.execute(
                    () -> order.add("root"),
                    new Held(order, held),
                    () -> {
                      assertTrue(held.get());
                      throw failure;
                    },
                    () -> fail("no continuation after policy failure"))));
    assertEquals(List.of("root", "M-enter", "root", "M-close"), order);
    assertFalse(held.get());
  }

  @Test
  void mroot004ContinuationFailureRetainsIdentityUntilMCloses() {
    var order = new ArrayList<String>();
    var held = new AtomicBoolean();
    var failure = new IOException("downstream failed");
    assertSame(
        failure,
        assertThrows(
            IOException.class,
            () ->
                MorningRootScope.execute(
                    () -> order.add("root"),
                    new Held(order, held),
                    () -> order.add("policy"),
                    () -> {
                      assertTrue(held.get());
                      throw failure;
                    })));
    assertEquals(List.of("root", "M-enter", "root", "policy", "root", "M-close"), order);
    assertFalse(held.get());
  }

  @Test
  void mroot005NullBoundaryAndRootRecheckFailure() {
    var order = new ArrayList<String>();
    var held = new AtomicBoolean();
    var lock = new Held(order, held);
    MorningRootScope.Gate root = () -> order.add("root");
    MorningRootScope.Policy policy = () -> order.add("policy");
    LinuxFileLock.Operation<Boolean> continuation = () -> true;
    assertThrows(
        NullPointerException.class,
        () -> MorningRootScope.execute(null, lock, policy, continuation));
    assertThrows(
        NullPointerException.class,
        () -> MorningRootScope.execute(root, null, policy, continuation));
    assertThrows(
        NullPointerException.class, () -> MorningRootScope.execute(root, lock, null, continuation));
    assertThrows(
        NullPointerException.class, () -> MorningRootScope.execute(root, lock, policy, null));
    assertThrows(
        NullPointerException.class, () -> MorningRootScope.execute(root, lock, policy, () -> null));
    assertFalse(held.get());
    order.clear();
    var failure = new IOException("root changed");
    assertSame(
        failure,
        assertThrows(
            IOException.class,
            () ->
                MorningRootScope.execute(
                    () -> {
                      order.add("root");
                      if (order.size() == 8) throw failure;
                    },
                    lock,
                    policy,
                    continuation)));
    assertEquals(
        List.of("root", "M-enter", "root", "policy", "root", "root", "M-close", "root"), order);
    assertFalse(held.get());
  }

  @Test
  void mroot006EveryRootRecheckStopsAtItsOwnBoundary() {
    for (int failedCheck = 1; failedCheck <= 5; failedCheck++) {
      var order = new ArrayList<String>();
      var held = new AtomicBoolean();
      var failure = new IOException("root changed");
      var checks = new int[1];
      int target = failedCheck;
      assertSame(
          failure,
          assertThrows(
              IOException.class,
              () ->
                  MorningRootScope.execute(
                      () -> {
                        if (++checks[0] == target) throw failure;
                        order.add("root");
                      },
                      new Held(order, held),
                      () -> order.add("policy"),
                      () -> {
                        order.add("continuation");
                        return true;
                      })));
      assertFalse(held.get());
      assertEquals(target, checks[0]);
      assertEquals(target > 2 ? 1 : 0, order.stream().filter("policy"::equals).count());
      assertEquals(target > 3 ? 1 : 0, order.stream().filter("continuation"::equals).count());
      assertEquals(target > 1 ? 1 : 0, order.stream().filter("M-close"::equals).count());
    }
  }
}

package dev.codex.schubert.nk.batch.file;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.fail;

import dev.codex.schubert.nk.storage.ServiceConfigFiles;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

/** READY428007..009: literal owner order, no native ready or fake completed graph. */
final class MorningStartupLaunchOwnerTest {
  @Test
  void sequence428007ApiThenWebBorrowSameApiAndNeverStopOnTrueCompletion() throws Exception {
    var events = new ArrayList<String>();
    MorningStartupLaunchOwner.sequence(
        (service, earlier) -> {
          assertEquals(
              service == ServiceConfigFiles.Service.API ? List.of() : List.of("API"), earlier);
          assertThrows(UnsupportedOperationException.class, () -> earlier.add("extra"));
          events.add("start:" + service);
          return service.name();
        },
        slot -> fail("success must retain live service"),
        started -> {
          assertEquals(List.of("API", "WEB"), started);
          assertThrows(UnsupportedOperationException.class, () -> started.add("extra"));
          events.add("complete");
        });
    assertEquals(List.of("start:API", "start:WEB", "complete"), events);
  }

  @Test
  void sequence428008FailedStageClosesOnlyReturnedOwnersInReverseOrder() {
    for (int stage : List.of(0, 1, 2))
      for (Throwable failure :
          List.of(
              new IOException("golden"),
              new IllegalStateException("golden"),
              new AssertionError("golden"))) {
        var events = new ArrayList<String>();
        int failAt = stage;
        Throwable actual =
            assertThrows(
                failure.getClass(),
                () ->
                    MorningStartupLaunchOwner.sequence(
                        (service, earlier) -> {
                          events.add("start:" + service);
                          if (earlier.size() == failAt) raise(failure);
                          return service.name();
                        },
                        slot -> events.add("stop:" + slot),
                        started -> {
                          events.add("complete");
                          raise(failure);
                        }));
        assertSame(failure, actual);
        assertEquals(
            switch (stage) {
              case 0 -> List.of("start:API");
              case 1 -> List.of("start:API", "start:WEB", "stop:API");
              default -> List.of("start:API", "start:WEB", "complete", "stop:WEB", "stop:API");
            },
            events);
      }
  }

  @Test
  void sequence428009NullContractsCannotMintReturnedOwnership() {
    assertThrows(
        NullPointerException.class,
        () -> MorningStartupLaunchOwner.sequence(null, ignored -> {}, ignored -> {}));
    assertThrows(
        NullPointerException.class,
        () -> MorningStartupLaunchOwner.sequence((s, e) -> s, null, ignored -> {}));
    assertThrows(
        NullPointerException.class,
        () -> MorningStartupLaunchOwner.sequence((s, e) -> s, ignored -> {}, null));
    var closed = new ArrayList<String>();
    assertThrows(
        NullPointerException.class,
        () ->
            MorningStartupLaunchOwner.<String>sequence(
                (service, earlier) -> service == ServiceConfigFiles.Service.API ? "API" : null,
                closed::add,
                ignored -> {
                  fail("not complete");
                }));
    assertEquals(List.of("API"), closed);
  }

  private static void raise(Throwable failure) throws IOException {
    if (failure instanceof IOException checked) throw checked;
    if (failure instanceof RuntimeException unchecked) throw unchecked;
    throw (Error) failure;
  }
}

