      "NKROOTS1\n"
          + "boot_id=11111111-1111-4111-8111-111111111111\n"
          + "epoch_id=22222222-2222-4222-8222-222222222222\n"
          + "run_id=33333333-3333-4333-8333-333333333333\n"
