                f.f.epoch + ".permit",
                f.f.epoch + ".owner",
                f.f.epoch + ".API.launch",
                f.f.epoch + ".WEB.launch"),
            paths
                .map(p -> p.getFileName().toString())
                .collect(java.util.stream.Collectors.toSet()));
      }
      assertThrows(IOException.class, permits::readIssued);
    }
