  @Test
  void pairValueRejectsEverySharedInvariantBeforeBorrowingAuthority() throws Exception {
    try (var f = new Fixture()) {
      var pair = f.observe();
      var api = pair.api();
      var web = pair.web();
      var changedEpoch =
          new StartupPermitRecords.Epoch(
              StartupPermitRecords.State.INVALID,
              web.invalid().boot(),
              UUID.fromString("41100027-4444-4333-8444-555555555555"),
              web.invalid().activation(),
              Optional.empty());
      var changedPermit =
          StartupPermitRecords.readPermit(
              RootFailedStartRecoveryTest.PERMIT
                  .replace("release_sha256=" + "b".repeat(64), "release_sha256=" + "1".repeat(64))
                  .getBytes(java.nio.charset.StandardCharsets.US_ASCII));
      var owner = web.owner();
      var changedOwner =
          new dev.codex.schubert.nk.bootstrap.MaintenanceOwnerFrame(
              owner.boot(),
              owner.run(),
              owner.activation(),
              owner.cutoff(),
              owner.epoch(),
              owner.morning(),
              owner.cleanup(),
              owner.deadlineNanos() + 1);
      for (var changed :
          List.of(
              new RootFailedStartRecovery.Evidence(
                  api.invalid().issued(api.permitSha256()),
                  api.permit(),
                  api.permitSha256(),
                  api.owner(),
                  api.service(),
                  api.child()),
              new RootFailedStartRecovery.Evidence(
                  api.invalid(),
                  api.permit(),
                  api.permitSha256(),
                  api.owner(),
                  ServiceConfigFiles.Service.WEB,
                  api.child())))
        assertThrows(
            IllegalArgumentException.class,
            () -> new RootFailedStartRecovery.PairEvidence(changed, web));
      for (var changed :
          List.of(
              new RootFailedStartRecovery.Evidence(
                  changedEpoch,
                  web.permit(),
                  web.permitSha256(),
                  web.owner(),
                  web.service(),
                  web.child()),
              new RootFailedStartRecovery.Evidence(
                  web.invalid(),
                  changedPermit,
                  web.permitSha256(),
                  web.owner(),
                  web.service(),
                  web.child()),
              new RootFailedStartRecovery.Evidence(
                  web.invalid(),
                  web.permit(),
                  "1".repeat(64),
                  web.owner(),
                  web.service(),
                  web.child()),
              new RootFailedStartRecovery.Evidence(
                  web.invalid(),
                  web.permit(),
                  web.permitSha256(),
                  changedOwner,
                  web.service(),
                  web.child()),
