/** ROOTREC001/003/004: real FD IO, explicitly synthetic root/tmpfs; not native authority. */
final class RootFailedStartRecoveryTest {
  @TempDir Path temporary;
  static final String PERMIT =
      "NKPERMIT1\n"
          + StartupLaunchFilesTest.BIND
          + "broker_invocation_id="
          + "2".repeat(32)
          + "\nrelease_sha256="
          + "b".repeat(64)
          + "\napi_config_sha256="
          + "c".repeat(64)
          + "\nweb_config_sha256="
          + "d".repeat(64)
          + "\nroots_sha256="
          + "e".repeat(64)
          + "\nprestart_steps_sha256="
          + "f".repeat(64)
          + "\n";

  final class Fixture implements AutoCloseable, StartupPermitFiles.Io {
    final BackupPublicationFixture f;
    final String service;
    final String epoch = StartupLaunchFilesTest.EPOCH;
    final String sha;

    Fixture(String service) throws Exception {
      this.service = service;
      f = new BackupPublicationFixture(temporary);
      Files.delete(f.child);
      f.metadata =
          (role, values) -> {
            values.put("uid", 0);
            values.put("gid", 0);
          };
      sha =
          HexFormat.of()
              .formatHex(
                  MessageDigest.getInstance("SHA-256")
                      .digest(PERMIT.getBytes(StandardCharsets.US_ASCII)));
      put(
          "epoch.current",
          "NKEPOCH1\nstate=INVALID\n" + StartupLaunchFilesTest.BIND + "permit_sha256=-\n");
      put(epoch + ".permit", PERMIT);
      put(epoch + ".owner", StartupLaunchFilesTest.OWNER);
      put(
          epoch + "." + service + ".launch",
          StartupLaunchRecordTest.GOLD
              .replace("service=API", "service=" + service)
              .replace("a".repeat(64), sha)
              .replace(
                  "b".repeat(64),
                  HexFormat.of()
                      .formatHex(
                          MessageDigest.getInstance("SHA-256")
                              .digest(
                                  StartupLaunchFilesTest.OWNER.getBytes(
                                      StandardCharsets.US_ASCII)))));
      put(epoch + "." + service + ".start.intent", "");
      put("permit-start.intent", "");
    }

    void put(String name, String value) throws IOException {
      Files.writeString(f.parent.resolve(name), value);
      Files.setAttribute(f.parent.resolve(name), "unix:mode", 0600);
    }

    RootFailedStartRecovery.Evidence observe() throws IOException {
      return RootFailedStartRecovery.observe(f.root, f, this);
    }

    void retire(RootFailedStartRecovery.Evidence e, RootFailedStartRecovery.Proof proof)
        throws IOException {
      RootFailedStartRecovery.retire(f.root, f, this, e, proof);
    }

    public Map<String, Object> attributes(Path p) throws IOException {
      return f.attributes(p);
    }

    public String filesystem(Path p) {
      return f.filesystem(p);
    }

    public SeekableByteChannel open(Path p) throws IOException {
      return f.open(p);
    }

    public InspectorEnvironmentPublisher.Writer openWriter(Path p) throws IOException {
      return f.openWriter(p);
    }

    public void replace(Path d, String p, String c) {
      throw new AssertionError("recovery must never replace current");
    }

    public MessageDigest digest() throws NoSuchAlgorithmException {
      return MessageDigest.getInstance("SHA-256");
    }

    public void close() throws dev.codex.schubert.nk.storage.StorageIoException {
      f.close();
    }
  }

  @Test
  void bothClosedRolesRetireOnlyTwoIntentsAndPreserveInvalidAndArtifacts() throws Exception {
    for (String role : List.of("API", "WEB"))
      try (var f = new Fixture(role)) {
        var before = new HashMap<String, String>();
        for (var name :
            List.of(
                "epoch.current",
                f.epoch + ".permit",
                f.epoch + ".owner",
                f.epoch + "." + role + ".launch"))
          before.put(name, Files.readString(f.f.parent.resolve(name)));
        var evidence = f.observe();
        assertEquals(f.sha, evidence.permitSha256());
        assertEquals(role, evidence.service().name());
        assertEquals(StartupPermitRecords.State.INVALID, evidence.invalid().state());
        assertEquals("FailedRootEvidence[actual=<redacted>]", evidence.toString());
        var proofs = new ArrayList<RootFailedStartRecovery.Evidence>();
        f.retire(evidence, proofs::add);
        assertFalse(proofs.isEmpty());
        assertTrue(proofs.stream().allMatch(evidence::equals));
        assertFalse(Files.exists(f.f.parent.resolve(f.epoch + "." + role + ".start.intent")));
        assertFalse(Files.exists(f.f.parent.resolve("permit-start.intent")));
        for (var entry : before.entrySet())
          assertEquals(entry.getValue(), Files.readString(f.f.parent.resolve(entry.getKey())));
        var permits = new StartupPermitFiles(f.f.root, f.f, f, UUID::randomUUID);
        assertThrows(IOException.class, permits::readIssued);
        assertEquals(
            f.sha,
            permits.readRevoked(evidence.invalid()).formerIssued().permitDigest().orElseThrow());
        assertThrows(IOException.class, f::observe);
      }
  }

  @Test
  void unknownOrMissingAndProofFailurePreserveQuarantine() throws Exception {
    for (String bad :
        List.of("unknown", "stray.part", "41100027-4444-4333-8444-555555555555.API.start.intent"))
      try (var f = new Fixture("API")) {
        f.put(bad, "");
        assertThrows(IOException.class, f::observe);
        assertTrue(Files.exists(f.f.parent.resolve("permit-start.intent")));
      }
    try (var f = new Fixture("API")) {
      var e = f.observe();
      assertThrows(
          IOException.class,
          () ->
              f.retire(
                  e,
                  ignored -> {
                    throw new IOException("synthetic actual closure unavailable");
                  }));
      assertTrue(Files.exists(f.f.parent.resolve(f.epoch + ".API.start.intent")));
      assertTrue(Files.exists(f.f.parent.resolve("permit-start.intent")));
      assertThrows(NullPointerException.class, () -> f.retire(null, ignored -> {}));
      assertThrows(NullPointerException.class, () -> f.retire(e, null));
      f.put(f.epoch + ".WEB.start.intent", "");
      assertThrows(IOException.class, f::observe);
      Files.delete(f.f.parent.resolve(f.epoch + ".WEB.start.intent"));
      f.put("permit-start.intent", "nonempty");
      assertThrows(IOException.class, () -> f.retire(e, ignored -> {}));
    }
  }

  @Test
  void syncFailureAfterLastUnlinkMustRemainQuarantined() throws Exception {
    try (var f = new Fixture("API")) {
      var e = f.observe();
      var injected = new java.util.concurrent.atomic.AtomicBoolean();
      f.f.hook =
          (name, count) -> {
            if (name.equals("sync")
                && !Files.exists(f.f.parent.resolve("permit-start.intent"))
                && injected.compareAndSet(false, true))
              f.f.faults.put("sync#" + count, new IOException("synthetic post-unlink sync fault"));
          };
      assertThrows(IOException.class, () -> f.retire(e, ignored -> {}));
      assertTrue(injected.get());
      assertTrue(
          Files.exists(f.f.parent.resolve("permit-start.intent")),
          "unknown durability cannot become clear");
      assertEquals(
          e.invalid(), new StartupPermitFiles(f.f.root, f.f, f, UUID::randomUUID).current());
    }
  }

  @Test
  void changedOwnerPermitCurrentAndInterruptedNeverRetire() throws Exception {
    for (String name : List.of("epoch.current", "permit", "owner", "API.launch"))
      try (var f = new Fixture("API")) {
        var e = f.observe();
        f.put(name.equals("epoch.current") ? name : f.epoch + "." + name, "corrupt");
        assertThrows(IOException.class, () -> f.retire(e, ignored -> fail("changed evidence")));
        assertTrue(Files.exists(f.f.parent.resolve("permit-start.intent")));
      }
    try (var f = new Fixture("API")) {
      var e = f.observe();
      Thread.currentThread().interrupt();
      try {
        assertThrows(IOException.class, () -> f.retire(e, ignored -> fail("interrupted")));
      } finally {
        Thread.interrupted();
      }
      assertTrue(Files.exists(f.f.parent.resolve("permit-start.intent")));
    }
  }
}

package dev.codex.schubert.nk.batch.file;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import dev.codex.schubert.nk.batch.platform.RootStartupContext;
import dev.codex.schubert.nk.bootstrap.MaintenanceOwnerFrame;
import dev.codex.schubert.nk.storage.ServiceConfigFiles;
import dev.codex.schubert.nk.storage.StorageIoException;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.UUID;
import org.junit.jupiter.api.Test;

/** PT-ROOTWAIT-SSC307-001..012: literal sequence/clock/identity oracles, no native authority. */
final class RootPendingWaitTest {
  private static RootStartupContext.Snapshot self(ServiceConfigFiles.Service service) {
    var role = RootStartupContext.Service.valueOf(service.name());
    return new RootStartupContext.Snapshot(
        role,
        "31100027-3333-4333-8444-555555555555",
        "2".repeat(32),
        300,
        200,
        9,
        "/system.slice/" + role.unit());
  }

  private static StartupLaunchRecord record(ServiceConfigFiles.Service service, long pid) {
    return new StartupLaunchRecord(
        service,
        UUID.fromString("31100027-3333-4333-8444-555555555555"),
        UUID.fromString("31100027-4444-4333-8444-555555555555"),
        "a".repeat(64),
        "b".repeat(64),
        new MaintenanceOwnerFrame.Parent("2".repeat(32), pid, 200));
  }

  @Test
  void pending001ImmediateBothServicesHaveExactObservationOrder() throws Exception {
    for (var service : ServiceConfigFiles.Service.values()) {
      var io = new Fake(10, 11);
      io.launches = List.of(Optional.of(record(service, 300)));
      RootStartupPending.awaitLaunch(self(service), 100, io);
      assertEquals(List.of("clock:10", "owner:1", "read:1", "owner:2", "clock:11"), io.events);
    }
    var boundary = new Fake(99, 99);
    RootStartupPending.awaitLaunch(self(ServiceConfigFiles.Service.API), 100, boundary);
    assertEquals(List.of("clock:99", "owner:1", "read:1", "owner:2", "clock:99"), boundary.events);
  }

  @Test
  void pending002MissingTwiceUsesSameDeadlineAndExactOrder() throws Exception {
    var io = new Fake(1, 2, 3, 4);
    io.launches =
        List.of(
            Optional.empty(),
            Optional.empty(),
            Optional.of(record(ServiceConfigFiles.Service.API, 300)));
    RootStartupPending.awaitLaunch(self(ServiceConfigFiles.Service.API), 100, io);
    assertEquals(
        List.of(
            "clock:1", "owner:1", "read:1", "pause:1", "clock:2", "owner:2", "read:2", "pause:2",
            "clock:3", "owner:3", "read:3", "owner:4", "clock:4"),
        io.events);
  }

  @Test
  void pending003EqualOrPastDeadlineRejectsBeforeOwner() {
    for (long value : new long[] {100, 101}) {
      var io = new Fake(value);
      unavailable(
          () -> RootStartupPending.awaitLaunch(self(ServiceConfigFiles.Service.API), 100, io));
      assertEquals(List.of("clock:" + value), io.events);
    }
  }

  @Test
  void pending004MissingCannotRestartOrExtendDeadline() {
    var io = new Fake(99, 100);
    io.launches = List.of(Optional.empty());
    unavailable(
        () -> RootStartupPending.awaitLaunch(self(ServiceConfigFiles.Service.API), 100, io));
    assertEquals(List.of("clock:99", "owner:1", "read:1", "pause:1", "clock:100"), io.events);
  }

  @Test
  void pending005FinalDeadlineIsStrictAndAfterOwner() {
    for (long value : new long[] {100, 101}) {
      var io = new Fake(99, value);
      unavailable(
          () -> RootStartupPending.awaitLaunch(self(ServiceConfigFiles.Service.API), 100, io));
      assertEquals(
          List.of("clock:99", "owner:1", "read:1", "owner:2", "clock:" + value), io.events);
    }
  }

  @Test
  void pending006EitherOwnerFailureStopsWithoutLaterObservation() {
    for (int index : new int[] {1, 2}) {
      var io = new Fake(10);
      var failure = new IOException("PUBLIC_OWNER_FAILURE");
      io.failAt = "owner:" + index;
      io.failure = failure;
      assertSame(
          failure,
          assertThrows(
              IOException.class,
              () -> RootStartupPending.awaitLaunch(self(ServiceConfigFiles.Service.API), 100, io)));
      assertEquals(
          index == 1
              ? List.of("clock:10", "owner:1")
              : List.of("clock:10", "owner:1", "read:1", "owner:2"),
          io.events);
    }
  }

  @Test
  void pending007UnknownClockOwnerReadAndPauseFailuresKeepIdentity() {
    for (String event : List.of("clock:10", "owner:1", "read:1", "pause:1")) {
      for (Throwable failure :
          List.of(
              new IOException("PUBLIC_IO"),
              new IllegalStateException("PUBLIC_RUNTIME"),
              new AssertionError("PUBLIC_ERROR"))) {
        if (event.equals("pause:1") && failure instanceof IOException) continue;
        var io = new Fake(10);
        io.failAt = event;
        io.failure = failure;
        if (event.equals("pause:1")) io.launches = List.of(Optional.empty());
        assertSame(
            failure,
            assertThrows(
                failure.getClass(),
                () ->
                    RootStartupPending.awaitLaunch(self(ServiceConfigFiles.Service.API), 100, io)));
        assertEquals(event, io.events.getLast());
      }
    }
  }

  @Test
  void pending008WrongChildGenerationStopsBeforeSecondOwner() {
    var io = new Fake(10);
    io.launches = List.of(Optional.of(record(ServiceConfigFiles.Service.API, 301)));
    unavailable(
        () -> RootStartupPending.awaitLaunch(self(ServiceConfigFiles.Service.API), 100, io));
    assertEquals(List.of("clock:10", "owner:1", "read:1"), io.events);
  }

  @Test
  void pending009InterruptedPauseRestoresFlagAndRedactsCause() {
    boolean wasInterrupted = Thread.currentThread().isInterrupted();
    try {
      var io = new Fake(10);
      io.launches = List.of(Optional.empty());
      io.interrupt = true;
      IOException failure =
          assertThrows(
              IOException.class,
              () -> RootStartupPending.awaitLaunch(self(ServiceConfigFiles.Service.API), 100, io));
      assertEquals("root launch unavailable", failure.getMessage());
      assertNull(failure.getCause());
      assertEquals(0, failure.getSuppressed().length);
      assertTrue(Thread.currentThread().isInterrupted());
      assertEquals(List.of("clock:10", "owner:1", "read:1", "pause:1"), io.events);
    } finally {
      Thread.interrupted();
      if (wasInterrupted) Thread.currentThread().interrupt();
    }
  }

  @Test
  void pending010NullBoundariesDoNotObserveNativeInputs() {
    var io = new Fake(10);
    assertThrows(NullPointerException.class, () -> RootStartupPending.awaitLaunch(null, 100, io));
    assertTrue(io.events.isEmpty());
    assertThrows(
        NullPointerException.class,
