      assertEquals("stopped-readback", stopped.events.getLast());
      stopped.current.set(StoppedBackupFixture.COLD);
      verify(f); // Full GC cold is accepted ONLY with this observed and explicitly stopped cycle.
      assertEquals(
          mode.equals("failed")
