          return attribute.equals("messageCount") ? pair[0] : pair[1];
        });
  }

  private static Map<String, long[]> zeroes() {
    var values = new HashMap<String, long[]>();
    for (String address : ADDRESSES) values.put(address + ".q", new long[] {0, 0});
