      assertTrue(unknown.observeTerminal(unknown.capture()).isEmpty());
    }
    var drift =
        new Script(oldState(), state(FRESH, "failed", "failed", "", "0", "1", "1", "exit-code"));
    drift.kernel = List.of(Optional.of(oldState()), Optional.of(fresh()));
