  @Test
  void bterm003EveryMetadataAndFilesystemCondition() {
    for (String role : ROLES) {
      for (String key : List.of("mode", "uid", "gid", "nlink", "size", "dev", "ino")) {
        for (int kind = 0; kind < 3; kind++) {
          var f = new Fixture();
          f.present = true;
          final int variant = kind;
          f.change =
              (r, m) -> {
                if (r.equals(role)) {
                  if (variant == 0) m.remove(key);
                  else if (variant == 1) m.put(key, null);
                  else m.put(key, "unknown");
                }
                return m;
              };
          rejected(f);
        }
      }
      for (var entry :
          Map.<String, Object>of(
                  "mode", 040777, "uid", 1, "gid", 1, "nlink", 1, "size", -1L, "dev", -1L, "ino",
                  0L)
              .entrySet()) {
        var f = new Fixture();
        f.present = true;
        f.change =
            (r, m) -> {
              if (r.equals(role)) m.put(entry.getKey(), entry.getValue());
