              consumeNanos(100_000_000L);
              return slowStart;
            });
    assertEquals(
        StopGateFailure.TIMEOUT,
        assertThrows(
                StopGateException.class, () -> reader.executeStreaming(COMMAND, 16, 50_000_000L))
            .reason());
    assertEquals(1, slowStart.stdoutClosed);
    assertEquals(1, slowStart.stdinClosed);
    assertEquals(1, slowStart.stderrClosed);
    assertFalse(slowStart.isAlive());
    var slowWait = new Child(new byte[0]);
    slowWait.waitDelayNanos = 100_000_000L;
    assertEquals(
        StopGateFailure.TIMEOUT,
        assertThrows(
                StopGateException.class,
                () -> reader(slowWait).executeStreaming(COMMAND, 16, 50_000_000L))
            .reason());
    assertEquals(1, slowWait.stdoutClosed);
    assertEquals(1, slowWait.stdinClosed);
    assertEquals(1, slowWait.stderrClosed);
    assertFalse(slowWait.isAlive());
  }

  @Test
  void inspector919004ExpiredStdoutDrainCancelsReaderAndClosesEveryStream() throws Exception {
    var blocked = new Child(new byte[0]);
    blocked.readDelayNanos = 5_000_000_000L;
    assertEquals(
        StopGateFailure.TIMEOUT,
        assertThrows(
                StopGateException.class,
                () -> reader(blocked).executeStreaming(COMMAND, 16, 1_000_000_000L))
            .reason());
    assertTrue(blocked.drainFinished.await(5, TimeUnit.SECONDS));
    assertEquals(1, blocked.stdoutClosed);
    assertEquals(1, blocked.stdinClosed);
    assertEquals(1, blocked.stderrClosed);
    assertFalse(blocked.isAlive());
  }

  private static void consumeNanos(long nanos) {
    long end = System.nanoTime() + nanos;
    while (System.nanoTime() < end && !Thread.currentThread().isInterrupted()) {
      java.util.concurrent.locks.LockSupport.parkNanos(
          Math.min(20_000_000L, end - System.nanoTime()));
    }
  }

  @Test
  void concurrentDrainAndOwnedStreams() {
    byte[] golden = new byte[131072];
    Arrays.fill(golden, (byte) 'J');
    var child = new Child(golden);
    assertArrayEquals(
        golden, reader(child).executeStreaming(COMMAND, golden.length, 2_000_000_000L));
    assertEquals(1, child.stdoutClosed);
    assertEquals(1, child.stdinClosed);
    assertEquals(1, child.stderrClosed);
    assertFalse(child.destroyed);
    assertTrue(child.waitBound > 0 && child.waitBound <= 2_000_000_000L);
    assertEquals(TimeUnit.NANOSECONDS, child.waitUnit);
  }

  @Test
  void sizeExitTimeoutAndInterruptedRemainFailures() {
    var large = new Child(new byte[17]);
    assertReason(StopGateFailure.MALFORMED_STATE, large, 16);
    var failed = new Child(new byte[0]);
    failed.exit = 7;
    assertReason(StopGateFailure.COMMAND_FAILURE, failed, 16);
    var timeout = new Child(new byte[0]);
    timeout.completed = false;
    assertReason(StopGateFailure.TIMEOUT, timeout, 16);
    assertTrue(timeout.destroyed);
    var interrupt = new Child(new byte[0]);
    interrupt.interrupt = true;
    try {
      assertReason(StopGateFailure.INTERRUPTED, interrupt, 16);
      assertTrue(Thread.currentThread().isInterrupted());
    } finally {
      Thread.interrupted();
    }
    assertThrows(StopGateException.class, () -> reader(failed).executeStreaming(COMMAND, 0, 1));
    assertThrows(StopGateException.class, () -> reader(failed).executeStreaming(COMMAND, 1, 0));
  }

  @Test
  void declaredReadFailureUnknownFailureAndCloseFailure() {
    var io = new Child(new byte[0]);
    io.readFailure = new IOException("fixture");
    assertReason(StopGateFailure.COMMAND_FAILURE, io, 16);
    for (Throwable unexpected :
        List.of(new IllegalStateException("fixture"), new AssertionError("fixture"))) {
      var child = new Child(new byte[0]);
      child.readFailure = unexpected;
      assertSame(
          unexpected,
          assertThrows(
              unexpected.getClass(),
              () -> reader(child).executeStreaming(COMMAND, 16, 2_000_000_000L)));
      assertEquals(1, child.stdoutClosed);
      assertEquals(1, child.stdinClosed);
      assertEquals(1, child.stderrClosed);
    }
    var close = new Child(new byte[0]);
    close.closeFailure = true;
    assertReason(StopGateFailure.COMMAND_FAILURE, close, 16);
    assertTrue(close.destroyed);
  }

  private static InspectorUnitProbe.NativeReader reader(Child child) {
    return new InspectorUnitProbe.NativeReader(
        command -> {
          assertEquals(COMMAND, command);
          return child;
        });
  }

  private static void assertReason(StopGateFailure reason, Child child, int limit) {
    assertEquals(
        reason,
        assertThrows(
                StopGateException.class,
                () -> reader(child).executeStreaming(COMMAND, limit, 2_000_000_000L))
            .reason());
    assertEquals(1, child.stdoutClosed);
    assertEquals(1, child.stdinClosed);
    assertEquals(1, child.stderrClosed);
  }

  private static final class Child extends Process {
    private final byte[] bytes;
    private int stdoutClosed;
    private int stdinClosed;
    private int stderrClosed;
    private int exit;
    private boolean completed = true;
    private boolean alive = true;
    private boolean destroyed;
    private boolean interrupt;
    private boolean closeFailure;
    private Throwable readFailure;
    private long waitBound;
    private TimeUnit waitUnit;
    private long waitDelayNanos;
    private long readDelayNanos;
    private final CountDownLatch drainStarted = new CountDownLatch(1);
    private final CountDownLatch drainFinished = new CountDownLatch(1);

    Child(byte[] bytes) {
      this.bytes = bytes;
    }

    @Override
    public InputStream getInputStream() {
      return new ByteArrayInputStream(bytes) {
        @Override
        public byte[] readNBytes(int count) throws IOException {
          assertTrue(Thread.currentThread().isVirtual());
          if (readDelayNanos > 0) {
            drainStarted.countDown();
            try {
              consumeNanos(readDelayNanos);
              if (Thread.currentThread().isInterrupted())
                throw new InterruptedIOException("fixture cancelled");
            } finally {
              drainFinished.countDown();
            }
          }
          if (readFailure instanceof IOException failure) throw failure;
          if (readFailure instanceof RuntimeException failure) throw failure;
          if (readFailure instanceof Error failure) throw failure;
          return super.readNBytes(count);
        }

        @Override
        public void close() {
          stdoutClosed++;
        }
      };
    }

    @Override
    public OutputStream getOutputStream() {
      return new ByteArrayOutputStream() {
        @Override
        public void close() throws IOException {
          stdinClosed++;
          if (closeFailure) throw new IOException("fixture");
        }
      };
    }

    @Override
    public InputStream getErrorStream() {
      return new ByteArrayInputStream(new byte[0]) {
        @Override
        public void close() {
          stderrClosed++;
        }
      };
    }

    @Override
    public int waitFor() {
      throw new AssertionError("unbounded wait forbidden");
    }

    @Override
    public boolean waitFor(long timeout, TimeUnit unit) throws InterruptedException {
      waitBound = timeout;
      waitUnit = unit;
      if (interrupt) throw new InterruptedException("fixture");
      if (readDelayNanos > 0) assertTrue(drainStarted.await(5, TimeUnit.SECONDS));
      if (waitDelayNanos > 0) consumeNanos(waitDelayNanos);
      alive = !completed;
      return completed;
    }

    @Override
    public int exitValue() {
      assertFalse(alive);
      return exit;
    }

    @Override
    public boolean isAlive() {
      return alive;
    }

    @Override
    public void destroy() {
      destroyed = true;
      alive = false;
    }
  }
}

package dev.codex.schubert.nk.batch.platform;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.fail;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.Test;

/** SS342 SSC186; PT-OPS-CADDYFENCE001..003. Independent literal ownership order. */
final class CaddyAdmissionFenceTest {
  private static final List<String> ORDER =
      List.of(
          "full",
          "API-context",
          "owner",
          "API-marker",
          "owner",
          "API-context",
          "WEB-context",
          "owner",
          "WEB-marker",
          "owner",
          "WEB-context",
          "full");

  @FunctionalInterface
  interface Check {
    void run(String event) throws IOException;
  }

  static BackupUnitStartClient.Attempt attempt(MaintenanceUnit unit, Check check, int[] starts)
      throws IOException {
    var child = new InspectorUnitProbeFixture.Child(new byte[0]);
    child.waitSeconds = 120;
    return new BackupUnitStartClient(
            () -> check.run(unit.name() + "-context"),
            () -> {},
            command -> {
              starts[0]++;
              assertEquals(unit.serviceName(), command.getLast());
              return child;
            },
            () ->
                new BackupUnitStartClient.MarkerLease() {
                  public void retire() {
                    fail("admission cannot retire");
                  }

                  public void requireRetained() throws IOException {
                    check.run(unit.name() + "-marker");
                  }

                  public void closeObservation() {}
                },
            unit,
            Optional.empty())
        .start();
  }

  @Test
  void caddyfence001FullPeerDbChecksBracketBothPureOwnersWithoutReentry() throws Exception {
    var events = new ArrayList<String>();
    var starts = new int[1];
    boolean[] armed = {false};
    Check check =
        e -> {
          if (armed[0]) events.add(e);
        };
    var api = attempt(MaintenanceUnit.API, check, starts);
    var web = attempt(MaintenanceUnit.WEB, check, starts);
    var fence =
        BackupUnitStartClient.caddyAdmissionFence(
            () -> check.run("full"), () -> check.run("owner"), api, web);
    armed[0] = true;
    fence.verify();
    assertEquals(ORDER, events);
    assertEquals(2, Collections.frequency(events, "full"));
    assertEquals(4, Collections.frequency(events, "owner"));
    assertEquals(2, starts[0]);
    assertEquals(BackupUnitStartClient.Status.CLIENT_EXITED_ZERO, api.status());
    assertEquals(BackupUnitStartClient.Status.CLIENT_EXITED_ZERO, web.status());
  }

  @Test
  void caddyfence002EveryBeforeMarkerAndAfterFaultPreservesIdentityAndStopsLaterChecks()
      throws Exception {
    for (int point = 0; point < ORDER.size(); point++)
      for (Throwable fault :
          List.of(
              new IOException("independent-io"),
              new IllegalStateException("independent-runtime"),
              new AssertionError("independent-error"))) {
        int failAt = point;
        var events = new ArrayList<String>();
        var starts = new int[1];
        boolean[] armed = {false};
        Check check =
            e -> {
              if (!armed[0]) return;
              events.add(e);
              if (events.size() == failAt + 1) {
                if (fault instanceof IOException io) throw io;
                if (fault instanceof RuntimeException runtime) throw runtime;
                throw (Error) fault;
              }
            };
        var api = attempt(MaintenanceUnit.API, check, starts);
        var web = attempt(MaintenanceUnit.WEB, check, starts);
        var fence =
            BackupUnitStartClient.caddyAdmissionFence(
                () -> check.run("full"), () -> check.run("owner"), api, web);
        armed[0] = true;
        assertSame(fault, assertThrows(fault.getClass(), fence::verify));
        assertEquals(ORDER.subList(0, failAt + 1), events);
        assertEquals(2, starts[0]);
      }
  }

  @Test
  void caddyfence003NullWrongRoleAndCloseOnlyIntentCannotPassAdmission() throws Exception {
    var starts = new int[1];
    Check check = e -> {};
    var api = attempt(MaintenanceUnit.API, check, starts);
    var web = attempt(MaintenanceUnit.WEB, check, starts);
    BackupUnitStartClient.RetirementGate gate = () -> {};
    assertThrows(
        NullPointerException.class,
        () -> BackupUnitStartClient.caddyAdmissionFence(null, gate, api, web));
    assertThrows(
        NullPointerException.class,
        () -> BackupUnitStartClient.caddyAdmissionFence(gate, null, api, web));
    assertThrows(
        NullPointerException.class,
        () -> BackupUnitStartClient.caddyAdmissionFence(gate, gate, null, web));
    assertThrows(
        NullPointerException.class,
        () -> BackupUnitStartClient.caddyAdmissionFence(gate, gate, api, null));
    assertThrows(
        IOException.class, () -> BackupUnitStartClient.caddyAdmissionFence(gate, gate, web, web));
    assertThrows(
        IOException.class, () -> BackupUnitStartClient.caddyAdmissionFence(gate, gate, api, api));
    var fence = BackupUnitStartClient.caddyAdmissionFence(gate, gate, api, web);
    api.preserveObservation();
    assertThrows(IOException.class, fence::verify);
    assertEquals(2, starts[0]);
  }
}

package dev.codex.schubert.nk.batch.platform;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import dev.codex.schubert.nk.storage.DirectoryCalls;
import dev.codex.schubert.nk.storage.ResourceScope;
import dev.codex.schubert.nk.storage.StorageIoException;
import java.io.IOException;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import org.junit.jupiter.api.Test;

/** OPS009/SYS002004/UI251/SS333343354/SSC308; PT-OPS-CGROUPFD001..008; synthetic FD only. */
final class CgroupPrimitiveOwnerTest {
  private static final String[] TYPE = {
    "NIREIIRERRRREEEE", "IIREIIRERRRREEEE", "RRRRRRRRRRRRRRRR", "EEEEEEEEEEEEEEEE"
  };
  private static final String[] SUPPRESSED = {
    "0000000001110111", "0000000001110111", "0111122212221222", "0111122212221222"
  };
  private static final String[] WINNER = {
    "xx22xx2211111111", "xx22xx2211111111", "0000000000000000", "0000000000000000"
  };

  private static final class Fixture implements AutoCloseable {
    final List<Integer> closed = new ArrayList<>();
    final List<String> opened = new ArrayList<>();
    final FixedUnitCgroupNamespace.Owner owner;
    int next = 319;
    Integer returned;
    Throwable opening;
    Throwable[] closing = new Throwable[0];

    Fixture() {
      DirectoryCalls calls =
          (DirectoryCalls)
              Proxy.newProxyInstance(
                  getClass().getClassLoader(),
                  new Class<?>[] {DirectoryCalls.class},
                  (proxy, method, args) -> {
                    switch (method.getName()) {
                      case "openRoot", "openDirectory" -> {
                        opened.add(method.getName());
                        if (opening != null) throw opening;
                        int value = returned == null ? next++ : returned;
                        returned = null;
                        return value;
                      }
                      case "close" -> {
                        closed.add((Integer) args[0]);
                        int index = closed.size() - 1;
                        if (index < closing.length && closing[index] != null) throw closing[index];
                        return null;
                      }
                      default -> throw new AssertionError("no other native capability");
                    }
                  });
      owner = new FixedUnitCgroupNamespace.Owner(calls);
    }

    void open(int count) throws StorageIoException {
      int current = owner.openRoot();
      for (int index = 1; index < count; index++)
        current = owner.openDirectory(current, "segment" + index);
    }

    @Override
    public void close() throws StorageIoException {
      owner.close();
    }
  }

  @Test
  void cgroupfd001SixPrimitiveHighDescriptorsKeepOriginalForwardCloseOrder() throws Exception {
    try (var fixture = new Fixture()) {
      fixture.open(6);
      for (int index = 0; index < 6; index++)
        assertEquals(319 + index, fixture.owner.descriptor(index));
      fixture.owner.close();
      fixture.owner.close();
      assertEquals(List.of(319, 320, 321, 322, 323, 324), fixture.closed);
      assertEquals(
          List.of(
              "openRoot",
              "openDirectory",
              "openDirectory",
              "openDirectory",
              "openDirectory",
              "openDirectory"),
          fixture.opened);
    }
  }

  @Test
  void cgroupfd002NullCapacityClosedAndForeignParentFailBeforeNativeIo() throws Exception {
    assertThrows(NullPointerException.class, () -> new FixedUnitCgroupNamespace.Owner(null));
    try (var fixture = new Fixture()) {
      assertThrows(NullPointerException.class, () -> fixture.owner.openDirectory(319, null));
      assertThrows(StorageIoException.class, () -> fixture.owner.openDirectory(319, "foreign"));
      assertTrue(fixture.opened.isEmpty());
      fixture.open(6);
      assertThrows(StorageIoException.class, fixture.owner::openRoot);
      assertThrows(StorageIoException.class, () -> fixture.owner.openDirectory(319, "full"));
      assertEquals(6, fixture.opened.size());
      fixture.owner.close();
      assertThrows(StorageIoException.class, fixture.owner::openRoot);
      assertThrows(StorageIoException.class, () -> fixture.owner.openDirectory(319, "closed"));
      assertEquals(6, fixture.opened.size());
      assertThrows(IndexOutOfBoundsException.class, () -> fixture.owner.descriptor(-1));
      assertThrows(IndexOutOfBoundsException.class, () -> fixture.owner.descriptor(6));
      assertEquals(List.of(319, 320, 321, 322, 323, 324), fixture.closed);
    }
    try (var fixture = new Fixture()) {
      fixture.open(1);
      assertThrows(StorageIoException.class, () -> fixture.owner.openDirectory(999, "foreign"));
      assertEquals(1, fixture.opened.size());
    }
    try (var fixture = new Fixture()) {
      fixture.owner.close();
      fixture.owner.close();
      assertTrue(fixture.closed.isEmpty());
    }
  }

  @Test
  void cgroupfd003NegativeAndDuplicateNeverOwnAnExtraFdButZeroIsValid() throws Exception {
    for (int kind = 0; kind < 2; kind++)
      for (int refused : new int[] {-1, 319, 320}) {
        try (var fixture = new Fixture()) {
          fixture.open(3);
          fixture.returned = refused;
          int selected = kind;
          assertThrows(StorageIoException.class, () -> open(fixture, selected));
          fixture.owner.close();
          assertEquals(List.of(319, 320, 321), fixture.closed);
          assertEquals(4, fixture.opened.size());
        }
      }
    try (var fixture = new Fixture()) {
      fixture.returned = 0;
      assertEquals(0, fixture.owner.openRoot());
      fixture.owner.close();
      assertEquals(List.of(0), fixture.closed);
    }
  }

  @Test
  void cgroupfd004AllOpenFailuresReleaseOnlyPreviouslyOwnedDescriptors() throws Exception {
    for (int kind = 0; kind < 2; kind++)
      for (int type = 1; type < 4; type++) {
        try (var fixture = new Fixture()) {
          fixture.open(1);
          fixture.opening = signal(type);
          int selected = kind;
          Throwable actual =
              assertThrows(
                  Throwable.class,
                  () ->
                      ResourceScope
                          .<FixedUnitCgroupNamespace.Owner, Integer, StorageIoException>acquire(
                              () -> fixture.owner,
                              FixedUnitCgroupNamespace.Owner::close,
                              owner -> open(fixture, selected)));
          if (type == 1)
            fixed(
                assertInstanceOf(StorageIoException.class, actual),
                StorageIoException.Reason.MISSING);
          else assertSame(fixture.opening, actual);
          assertEquals(List.of(319), fixture.closed);
          assertEquals(2, fixture.opened.size());
        }
      }
  }

  @Test
  void cgroupfd005All64ForwardCloseStatesMatchLiteralIndependentGolden() throws Exception {
    for (int first = 0; first < 4; first++)
      for (int middle = 0; middle < 4; middle++)
        for (int last = 0; last < 4; last++) {
          try (var fixture = new Fixture()) {
            fixture.closing = new Throwable[] {signal(first), signal(middle), signal(last)};
            fixture.open(3);
            Throwable actual = null;
            try {
              fixture.owner.close();
            } catch (Throwable observed) {
              actual = observed;
            }
            assertEquals(List.of(319, 320, 321), fixture.closed);
            int column = middle * 4 + last;
            char type = TYPE[first].charAt(column);
            if (type == 'N') assertNull(actual);
            else {
              assertNotNull(actual);
              assertEquals(SUPPRESSED[first].charAt(column) - '0', actual.getSuppressed().length);
              if (type == 'I') {
                int known = (first == 1 ? 1 : 0) + (middle == 1 ? 1 : 0) + (last == 1 ? 1 : 0);
                fixed(
                    assertInstanceOf(StorageIoException.class, actual),
                    known == 1
                        ? StorageIoException.Reason.MISSING
                        : StorageIoException.Reason.UNAVAILABLE);
              } else {
                int winner = WINNER[first].charAt(column) - '0';
                assertSame(fixture.closing[winner], actual);
                assertEquals(
                    type == 'R' ? IllegalStateException.class : AssertionError.class,
                    actual.getClass());
                for (Throwable secondary : actual.getSuppressed())
                  fixed(
                      assertInstanceOf(StorageIoException.class, secondary),
                      StorageIoException.Reason.UNAVAILABLE);
              }
            }
          }
        }
  }

  @Test
  void cgroupfd006ExistingAndRepeatedSuppressionKeepIdentityAndSanitizeLaterFailures()
      throws Exception {
    try (var fixture = new Fixture()) {
      var primary = new StorageIoException(StorageIoException.Reason.MISSING);
      primary.addSuppressed(new IOException("PUBLIC_PRIOR"));
      fixture.closing = new Throwable[] {primary, null, null};
      fixture.open(3);
      fixed(
          assertThrows(StorageIoException.class, fixture.owner::close),
          StorageIoException.Reason.UNAVAILABLE);
      assertEquals(List.of(319, 320, 321), fixture.closed);
    }
    try (var fixture = new Fixture()) {
      var primary = new IllegalStateException("PUBLIC_UNKNOWN");
      var prior = new IOException("PUBLIC_PRIOR");
      primary.addSuppressed(prior);
      fixture.closing = new Throwable[] {primary, primary, signal(1)};
      fixture.open(3);
      assertSame(primary, assertThrows(IllegalStateException.class, fixture.owner::close));
      assertEquals(3, primary.getSuppressed().length);
      assertSame(prior, primary.getSuppressed()[0]);
      for (int index = 1; index < 3; index++)
        fixed(
            assertInstanceOf(StorageIoException.class, primary.getSuppressed()[index]),
            StorageIoException.Reason.UNAVAILABLE);
      assertEquals(List.of(319, 320, 321), fixture.closed);
    }
  }

  @Test
  void cgroupfd007SixSlotsDrainEveryLaterFdBeforeUnknownAggregationAndNeverRetry()
      throws Exception {
    try (var fixture = new Fixture()) {
      Throwable unknown = signal(2);
      fixture.closing = new Throwable[] {signal(1), unknown, signal(1), signal(3), null, signal(1)};
      fixture.open(6);
      assertSame(unknown, assertThrows(IllegalStateException.class, fixture.owner::close));
      assertNotNull(unknown);
      assertEquals(3, unknown.getSuppressed().length);
      for (Throwable secondary : unknown.getSuppressed())
        fixed(
            assertInstanceOf(StorageIoException.class, secondary),
            StorageIoException.Reason.UNAVAILABLE);
      assertEquals(List.of(319, 320, 321, 322, 323, 324), fixture.closed);
      fixture.owner.close();
      assertEquals(6, fixture.closed.size());
      assertThrows(StorageIoException.class, fixture.owner::openRoot);
      assertEquals(6, fixture.opened.size());
    }
  }

  @Test
  void cgroupfd008ParallelOwnersNeverShareSlotsOrConsumeEachOther() throws Exception {
    var ready = new CountDownLatch(2);
    try (var first = new Fixture();
        var second = new Fixture();
        var executor = Executors.newFixedThreadPool(2)) {
      var a = executor.submit(() -> parallel(first, ready));
      var b = executor.submit(() -> parallel(second, ready));
      assertEquals(List.of(319, 320, 321), a.get());
      assertEquals(List.of(319, 320, 321), b.get());
      assertNotSame(first.owner, second.owner);
    }
  }

  private static List<Integer> parallel(Fixture fixture, CountDownLatch ready) throws Exception {
    fixture.open(3);
    ready.countDown();
    assertTrue(ready.await(10, TimeUnit.SECONDS));
    fixture.owner.close();
    return List.copyOf(fixture.closed);
  }

  private static int open(Fixture fixture, int kind) throws StorageIoException {
    return kind == 0 ? fixture.owner.openRoot() : fixture.owner.openDirectory(319, "next");
  }

  private static Throwable signal(int kind) {
    return switch (kind) {
      case 0 -> null;
      case 1 -> new StorageIoException(StorageIoException.Reason.MISSING);
      case 2 -> new IllegalStateException("PUBLIC_UNKNOWN");
      default -> new AssertionError("PUBLIC_UNKNOWN");
    };
  }

  private static void fixed(StorageIoException failure, StorageIoException.Reason reason) {
    assertEquals(reason, failure.reason());
    assertEquals("transfer storage operation failed", failure.getMessage());
    assertNull(failure.getCause());
    assertEquals(0, failure.getSuppressed().length);
  }
}

package dev.codex.schubert.nk.batch.platform;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
