      }
    }
  }

  @Test
  void queryown006InspectorRejectsEachMissingGetterBeforeNextInBothModes() {
    for (boolean streaming : List.of(false, true)) {
      for (int index = 0; index < 3; index++) {
        for (boolean missing : List.of(false, true)) {
