/** Independent inode, Unix attributes, byte and fault oracles. NK-MED-001; PT-MED-021..025. */
class ExistingFileAccessTest {
  @TempDir Path root;
  private StorageIdentity identity;

  @BeforeEach
  void prepare() throws Exception {
    directory(root);
    var attrs = Files.readAttributes(root, java.nio.file.attribute.PosixFileAttributes.class);
    identity = new StorageIdentity(attrs.owner().getName(), attrs.group().getName());
  }

  @Test
  void med021NestedAndLargeAssetsReadExactBytesAndCloseChannels() throws Exception {
    Path nested = Files.createDirectories(root.resolve("music/日本語 folder"));
    directory(root.resolve("music"));
    directory(nested);
    file(nested.resolve("音源.ogg"));
    try (var held = OwnedTransferDirectory.open(LinuxDirectoryCalls.create(), root)) {
      var access = new ExistingFileAccess(held, identity);
      AtomicReference<SeekableByteChannel> owned = new AtomicReference<>();
      assertArrayEquals(
          new byte[] {1, 2, 3},
          access.read(
              List.of("music", "日本語 folder", "音源.ogg"),
              3,
              channel -> {
                owned.set(channel);
                assertTrue(channel.isOpen());
                return bytes(channel);
              }));
      assertFalse(owned.get().isOpen());
      assertEquals(Boolean.TRUE, held.atDirectory(p -> Files.isDirectory(p)));
      Path large = root.resolve("large.flac");
      file(large);
      try (var writer = FileChannel.open(large, StandardOpenOption.WRITE)) {
        writer.position(48_000_001L);
        assertEquals(3, writer.write(ByteBuffer.wrap(new byte[] {11, 12, 13})));
      }
      assertArrayEquals(
          new byte[] {11, 12, 13},
          access.read(
              List.of("large.flac"),
              48_000_004L,
              channel -> {
                assertEquals(48_000_004L, channel.size());
                channel.position(48_000_001L);
                return bytes(channel);
              }));
      assertEquals(48_000_004L, Files.size(large));
    }
  }

  @Test
  void med022NullSizeAndSegmentContractsFailBeforeContentRead() throws Exception {
    try (var held = OwnedTransferDirectory.open(LinuxDirectoryCalls.create(), root)) {
      assertThrows(NullPointerException.class, () -> new ExistingFileAccess(null, identity));
      assertThrows(NullPointerException.class, () -> new ExistingFileAccess(held, null));
      assertThrows(NullPointerException.class, () -> new ExistingFileAccess(held, identity, null));
      var access = new ExistingFileAccess(held, identity);
      ExistingFileAccess.ReadOperation<Boolean> never = channel -> fail("invalid request read");
      assertThrows(NullPointerException.class, () -> access.read(null, 3, never));
      assertThrows(NullPointerException.class, () -> access.read(List.of("x"), 3, null));
      assertThrows(
          NullPointerException.class, () -> access.read(Arrays.asList("x", null), 3, never));
      assertThrows(IllegalArgumentException.class, () -> access.read(List.of(), 3, never));
      assertThrows(
          IllegalArgumentException.class,
          () -> access.read(java.util.Collections.nCopies(257, "a"), 3, never));
      for (long size : new long[] {0, -1, Long.MIN_VALUE}) {
        assertThrows(IllegalArgumentException.class, () -> access.read(List.of("x"), size, never));
      }
      for (String name : new String[] {"", ".", "..", "a/b", "a\0b"}) {
        assertThrows(IllegalArgumentException.class, () -> access.read(List.of(name), 3, never));
        assertThrows(
            IllegalArgumentException.class, () -> access.read(List.of(name, "x"), 3, never));
      }
      List<String> names = new ArrayList<>();
      Path current = root;
      for (int i = 0; i < 255; i++) {
        names.add("a");
        current = Files.createDirectory(current.resolve("a"));
        directory(current);
      }
      file(current.resolve("x"));
      names.add("x");
      assertArrayEquals(new byte[] {1, 2, 3}, access.read(names, 3, ExistingFileAccessTest::bytes));
    }
  }

  @Test
  void med023LinksMissingAndWrongUnixAttributesNeverExposeContent() throws Exception {
    Path nested = Files.createDirectory(root.resolve("nested"));
    directory(nested);
    Path target = nested.resolve("x");
    file(target);
    var held = OwnedTransferDirectory.open(LinuxDirectoryCalls.create(), root);
    var access = new ExistingFileAccess(held, identity);
    ExistingFileAccess.ReadOperation<Boolean> never = c -> fail("invalid inode content read");
    try (held) {
      reject(() -> access.read(List.of("missing"), 3, never));
      reject(() -> access.read(List.of("missing", "x"), 3, never));
      reject(() -> access.read(List.of("nested", "x", "x"), 3, never));
      Files.createSymbolicLink(root.resolve("link"), nested);
      reject(() -> access.read(List.of("link", "x"), 3, never));
      reject(() -> access.read(List.of("link"), 3, never));
      Files.createSymbolicLink(nested.resolve("symlink"), target);
      reject(() -> access.read(List.of("nested", "symlink"), 3, never));
      Files.createLink(nested.resolve("hard"), target);
      reject(() -> access.read(List.of("nested", "x"), 3, never));
      Files.delete(nested.resolve("hard"));
      reject(() -> access.read(List.of("nested", "x"), 4, never));
      for (Path changed : List.of(root, nested, target)) {
        var before = Files.getPosixFilePermissions(changed);
        Files.setPosixFilePermissions(changed, PosixFilePermissions.fromString("rwx------"));
        reject(() -> access.read(List.of("nested", "x"), 3, never));
        assertEquals(
            PosixFilePermissions.fromString("rwx------"), Files.getPosixFilePermissions(changed));
        Files.setPosixFilePermissions(changed, before);
      }
      reject(
          () ->
              new ExistingFileAccess(held, new StorageIdentity("different", identity.group()))
                  .read(List.of("nested", "x"), 3, never));
      reject(
          () ->
              new ExistingFileAccess(held, new StorageIdentity(identity.owner(), "different"))
                  .read(List.of("nested", "x"), 3, never));
      assertArrayEquals(new byte[] {1, 2, 3}, Files.readAllBytes(target));
      assertTrue(Files.isSymbolicLink(nested.resolve("symlink")));
      assertFalse(Files.exists(root.resolve("missing")));
    }
    reject(() -> access.read(List.of("nested", "x"), 3, never));
  }

  @Test
  void med024OpenReadAttributeAndCloseFailuresAreRedactedAndOwned() throws Exception {
    compoundOwnership();
    Path nested = Files.createDirectory(root.resolve("nested"));
    directory(nested);
    file(nested.resolve("x"));
    try (var held = OwnedTransferDirectory.open(LinuxDirectoryCalls.create(), root)) {
      for (String fault :
          List.of(
              "attrs1",
              "attrs2",
              "attrs3",
              "attrs4",
              "unsupported",
              "open",
              "size1",
              "size2",
              "wrong-size1",
              "wrong-size2",
              "close",
              "read",
              "callback-close",
              "bad-post")) {
        FaultIo io = new FaultIo(fault);
        var access = new ExistingFileAccess(held, identity, io);
        reject(
            () ->
                access.read(
                    List.of("nested", "x"),
                    3,
                    channel -> {
                      if (fault.equals("callback-close"))
                        throw new IOException("SYNTHETIC_PRIVATE_PATH");
                      return bytes(channel);
                    }));
        assertEquals(io.opens, io.closes);
        assertEquals(io.opens, io.channels.size());
        assertTrue(io.channels.stream().noneMatch(SeekableByteChannel::isOpen));
        assertEquals(Boolean.TRUE, held.atDirectory(Files::isDirectory));
        if (List.of("attrs1", "attrs2", "attrs3", "unsupported", "open").contains(fault)) {
          assertEquals(0, io.opens);
        }
      }
    }
    assertArrayEquals(new byte[] {1, 2, 3}, Files.readAllBytes(nested.resolve("x")));
  }

  @Test
  void med025ConcurrentAndReplacedNamesRetainIndependentInodes() throws Exception {
    Path nested = Files.createDirectory(root.resolve("nested"));
    directory(nested);
    file(nested.resolve("x"));
    try (var held = OwnedTransferDirectory.open(LinuxDirectoryCalls.create(), root);
        var executor = Executors.newVirtualThreadPerTaskExecutor()) {
      var access = new ExistingFileAccess(held, identity);
      synchronized (held) {
        var tasks = new ArrayList<java.util.concurrent.Future<byte[]>>();
        for (int i = 0; i < 100; i++) {
          tasks.add(
              executor.submit(
                  () -> {
                    FaultIo io = new FaultIo("none");
                    byte[] result =
                        new ExistingFileAccess(held, identity, io)
                            .read(
                                List.of("nested", "x"),
                                3,
                                channel -> {
                                  assertEquals(0, channel.position());
                                  return bytes(channel);
                                });
                    assertEquals(1, io.opens);
                    assertEquals(1, io.closes);
                    assertFalse(io.channels.getFirst().isOpen());
                    return result;
                  }));
        }
        for (var task : tasks)
          assertArrayEquals(new byte[] {1, 2, 3}, task.get(10, TimeUnit.SECONDS));
      }
      Path outside = Files.createDirectory(root.resolve("outside"));
      Files.write(outside.resolve("x"), new byte[] {9, 9, 9});
      assertArrayEquals(
          new byte[] {1, 2, 3},
          access.read(
              List.of("nested", "x"),
              3,
              channel -> {
                Files.move(nested.resolve("x"), nested.resolve("saved"));
                Files.createSymbolicLink(nested.resolve("x"), outside.resolve("x"));
                Files.move(nested, root.resolve("retained"));
                Files.createSymbolicLink(nested, outside);
                return bytes(channel);
              }));
      assertArrayEquals(new byte[] {9, 9, 9}, Files.readAllBytes(outside.resolve("x")));
      assertArrayEquals(
          new byte[] {1, 2, 3},
          access.read(List.of("retained", "saved"), 3, ExistingFileAccessTest::bytes));
      // Replace the configured root after admission. Held root must still select its old inode.
      Path old = root.resolveSibling(root.getFileName() + "-retained");
      Files.move(root, old);
      try {
        Files.createDirectory(root);
        assertArrayEquals(
            new byte[] {1, 2, 3},
            access.read(List.of("retained", "saved"), 3, ExistingFileAccessTest::bytes));
      } finally {
        Files.delete(root);
        Files.move(old, root);
      }
    }
  }

  private static void directory(Path path) throws IOException {
    Files.setPosixFilePermissions(path, PosixFilePermissions.fromString("rwxr-x---"));
  }

  private static void file(Path path) throws IOException {
    Files.write(path, new byte[] {1, 2, 3});
    Files.setPosixFilePermissions(path, PosixFilePermissions.fromString("rw-r-----"));
  }

  private static byte[] bytes(SeekableByteChannel channel) throws IOException {
    ByteBuffer bytes = ByteBuffer.allocate(3);
    while (bytes.hasRemaining()) assertTrue(channel.read(bytes) > 0);
    return bytes.array();
  }

  private static void reject(org.junit.jupiter.api.function.Executable action) {
    StorageIoException failure = assertThrows(StorageIoException.class, action);
    assertEquals(StorageIoException.Reason.UNAVAILABLE, failure.reason());
    assertEquals("transfer storage operation failed", failure.getMessage());
    assertNull(failure.getCause());
    assertEquals(0, failure.getSuppressed().length);
  }

  private void compoundOwnership() throws Exception {
    Path nested = Files.createDirectory(root.resolve("compound"));
    directory(nested);
    file(nested.resolve("x"));
    for (boolean childClose : List.of(false, true))
      for (boolean known : List.of(false, true))
        for (Throwable unknown :
            List.of(
                new IllegalStateException("public compound"),
                new NullPointerException("public compound"),
                new AssertionError("public compound"))) {
          var childDescriptors = new HashSet<Integer>();
          var childCloses = new AtomicInteger();
          DirectoryCalls nativeCalls = LinuxDirectoryCalls.create();
          DirectoryCalls calls =
              (DirectoryCalls)
                  Proxy.newProxyInstance(
                      getClass().getClassLoader(),
                      new Class<?>[] {DirectoryCalls.class},
                      (proxy, method, arguments) -> {
                        boolean released =
                            method.getName().equals("close")
                                && childDescriptors.remove((Integer) arguments[0]);
                        Object result;
                        try {
                          result = method.invoke(nativeCalls, arguments);
                        } catch (InvocationTargetException failure) {
                          throw failure.getCause();
                        }
                        if (method.getName().equals("openDirectory")
                            && arguments[1].equals("compound"))
                          assertTrue(childDescriptors.add((Integer) result));
                        if (released) {
                          childCloses.incrementAndGet();
                          if (childClose) raiseUnknown(unknown);
                        }
                        return result;
                      });
          try (var held = OwnedTransferDirectory.open(calls, root)) {
            var io = new FaultIo("none");
            if (!childClose) io.closeFailure = unknown;
            var access = new ExistingFileAccess(held, identity, io);
            assertSame(
                unknown,
                assertThrows(
                    unknown.getClass(),
                    () ->
                        access.read(
                            List.of("compound", "x"),
                            3,
                            channel -> {
                              assertArrayEquals(new byte[] {1, 2, 3}, bytes(channel));
                              if (known) throw new IOException("public I/O");
                              raiseUnknown(unknown);
                              return true;
                            })));
            assertEquals(1, io.opens);
            assertEquals(1, io.closes);
            assertTrue(io.channels.stream().noneMatch(SeekableByteChannel::isOpen));
            assertEquals(1, childCloses.get());
            assertTrue(childDescriptors.isEmpty());
            assertEquals(Boolean.TRUE, held.atDirectory(Files::isDirectory));
            assertEquals(known ? 0 : 1, unknown.getSuppressed().length);
            for (Throwable secondary : unknown.getSuppressed())
              reject(
                  () -> {
                    throw secondary;
                  });
          }
          assertArrayEquals(new byte[] {1, 2, 3}, Files.readAllBytes(nested.resolve("x")));
        }
  }

  private static void raiseUnknown(Throwable failure) {
    if (failure instanceof RuntimeException runtime) throw runtime;
    throw (Error) failure;
  }

  private static final class FaultIo implements ExistingFileAccess.Io {
    final String fault;
    final List<SeekableByteChannel> channels = new ArrayList<>();
    int attributes;
    int opens;
    int closes;
    Throwable closeFailure;

    FaultIo(String fault) {
      this.fault = fault;
    }

    @Override
    public Map<String, Object> attributes(Path held) throws IOException {
      attributes++;
      if (fault.equals("attrs" + attributes)) throw new IOException("SYNTHETIC_PRIVATE_PATH");
      if (fault.equals("unsupported"))
        throw new UnsupportedOperationException("SYNTHETIC_PRIVATE_PATH");
      Map<String, Object> result =
          new HashMap<>(Files.readAttributes(held, "unix:owner,group,mode,nlink,size"));
      if (fault.equals("bad-post") && attributes == 4) result.put("nlink", 2);
      return result;
    }

    @Override
    public SeekableByteChannel openReadOnly(Path path) throws IOException {
      if (fault.equals("open")) throw new IOException("SYNTHETIC_PRIVATE_PATH");
      SeekableByteChannel delegate = FileChannel.open(path, StandardOpenOption.READ);
      channels.add(delegate);
      opens++;
      return new SeekableByteChannel() {
        int sizes;

        @Override
        public int read(ByteBuffer bytes) throws IOException {
          if (fault.equals("read")) throw new IOException("SYNTHETIC_PRIVATE_PATH");
          return delegate.read(bytes);
        }

        @Override
        public int write(ByteBuffer bytes) {
          return fail("read-only capability write");
        }

        @Override
        public long position() throws IOException {
          return delegate.position();
        }

        @Override
        public SeekableByteChannel position(long value) throws IOException {
          delegate.position(value);
          return this;
        }

        @Override
        public long size() throws IOException {
          sizes++;
          if (fault.equals("size" + sizes)) throw new IOException("SYNTHETIC_PRIVATE_PATH");
          if (fault.equals("wrong-size" + sizes)) return 99;
          return delegate.size();
        }

        @Override
        public SeekableByteChannel truncate(long value) {
          return fail("read-only capability truncate");
        }

        @Override
        public boolean isOpen() {
          return delegate.isOpen();
        }

        @Override
        public void close() throws IOException {
          closes++;
          delegate.close();
          if (closeFailure != null) raiseUnknown(closeFailure);
          if (fault.equals("close") || fault.equals("callback-close"))
            throw new IOException("SYNTHETIC_PRIVATE_PATH");
        }
      };
    }
  }
}

package dev.codex.schubert.nk.storage;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.lang.foreign.Linker;
import java.lang.foreign.SymbolLookup;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.nio.file.attribute.PosixFilePermissions;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.Callable;
import java.util.concurrent.Executors;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/** Actual Linux syscalls against synthetic files only. SS333/SSC-019; PT-SCN-008-F01/F03. */
class LinuxDirectoryCallsTest {
  @TempDir Path root;

  @Test
  void transfer003EmptyDirectoryOnlyNeverRecursesOrFollowsSymlink() throws Exception {
    var calls = LinuxDirectoryCalls.create();
    try (var parent = OwnedTransferDirectory.open(calls, root)) {
      Files.createDirectory(root.resolve("empty"));
      parent.removeEmptyChild("empty");
      assertFalse(Files.exists(root.resolve("empty")));
      Files.createDirectory(root.resolve("nonempty"));
      Files.write(root.resolve("nonempty/file"), new byte[] {1, 2});
      assertThrows(StorageIoException.class, () -> parent.removeEmptyChild("nonempty"));
      assertArrayEquals(new byte[] {1, 2}, Files.readAllBytes(root.resolve("nonempty/file")));
      Files.createSymbolicLink(root.resolve("link"), root.resolve("nonempty"));
      assertThrows(StorageIoException.class, () -> parent.removeEmptyChild("link"));
      assertTrue(Files.isSymbolicLink(root.resolve("link")));
      for (String bad : List.of("", ".", "..", "a/b", "a\0b"))
        assertThrows(IllegalArgumentException.class, () -> parent.removeEmptyChild(bad));
      assertThrows(NullPointerException.class, () -> parent.removeEmptyChild(null));
      assertThrows(
          StorageIoException.class,
          () -> LinuxHostDirectoryCalls.create().removeEmptyDirectory(-1, "empty"));
    }
  }

  @Test
  void w01CreateNewHasOneWinnerAndPreservesExistingFileAndSymlinkTargets() throws Exception {
    DirectoryCalls calls = LinuxDirectoryCalls.create();
    int parent = open(calls, root);
    try (var executor = Executors.newFixedThreadPool(16)) {
      List<Callable<Integer>> tasks = new ArrayList<>();
      for (int i = 0; i < 100; i++) {
        int contender = i;
        tasks.add(
            () -> {
              int fd;
              try {
                fd = calls.createFile(parent, "same.part");
              } catch (StorageIoException failure) {
                assertEquals(StorageIoException.Reason.COLLISION, failure.reason());
                return -1;
              }
              try {
                Path handle = Path.of("/proc/self/fd", Integer.toString(fd));
                assertEquals(0100640, Files.getAttribute(handle, "unix:mode"));
                try (var stream =
                    java.nio.channels.FileChannel.open(handle, StandardOpenOption.WRITE)) {
                  assertEquals(
                      1, stream.write(java.nio.ByteBuffer.wrap(new byte[] {(byte) contender})));
                  stream.force(true);
                }
              } finally {
                calls.close(fd);
              }
              return contender;
            });
      }
      int winner = -1;
      int count = 0;
      for (var result : executor.invokeAll(tasks)) {
        int contender = result.get();
        if (contender >= 0) {
          winner = contender;
          count++;
        }
      }
      assertEquals(1, count);
      assertArrayEquals(new byte[] {(byte) winner}, Files.readAllBytes(root.resolve("same.part")));
      Files.createSymbolicLink(root.resolve("link.part"), root.resolve("same.part"));
      assertFailure(
          StorageIoException.Reason.COLLISION, () -> calls.createFile(parent, "link.part"));
      assertTrue(Files.isSymbolicLink(root.resolve("link.part")));
      assertArrayEquals(new byte[] {(byte) winner}, Files.readAllBytes(root.resolve("same.part")));
      for (String name : List.of("", ".", "..", "a/b", "a\0b", "/")) {
        assertThrows(IllegalArgumentException.class, () -> calls.createFile(parent, name));
      }
      assertThrows(NullPointerException.class, () -> calls.createFile(parent, null));
      assertFailure(StorageIoException.Reason.UNAVAILABLE, () -> calls.createFile(-1, "new.part"));
    } finally {
      calls.close(parent);
    }
  }

  @Test
  void f01NativeOperationsPreserveExistingTargetsAndBoundAllErrors() throws Exception {
    DirectoryCalls calls = LinuxDirectoryCalls.create();
    int fd = open(calls, root);
    try {
      calls.createDirectory(fd, "20260908");
      assertEquals(
          PosixFilePermissions.fromString("rwxr-x---"),
          Files.getPosixFilePermissions(root.resolve("20260908")));
      int child = calls.openDirectory(fd, "20260908");
      calls.sync(child);
      calls.close(child);
      assertFailure(
          StorageIoException.Reason.COLLISION, () -> calls.createDirectory(fd, "20260908"));
      assertFailure(StorageIoException.Reason.MISSING, () -> calls.openDirectory(fd, "missing"));
      Files.write(root.resolve("sample.part"), new byte[] {1, 2, 3}, StandardOpenOption.CREATE_NEW);
      Files.write(root.resolve("sample.ready"), new byte[] {7, 8}, StandardOpenOption.CREATE_NEW);
      assertFailure(
          StorageIoException.Reason.COLLISION,
          () -> calls.publish(fd, "sample.part", "sample.ready"));
      assertArrayEquals(new byte[] {1, 2, 3}, Files.readAllBytes(root.resolve("sample.part")));
      assertArrayEquals(new byte[] {7, 8}, Files.readAllBytes(root.resolve("sample.ready")));
      calls.publish(fd, "sample.part", "new.ready");
      calls.sync(fd);
      assertFalse(Files.exists(root.resolve("sample.part")));
      assertArrayEquals(new byte[] {1, 2, 3}, Files.readAllBytes(root.resolve("new.ready")));
      calls.unlink(fd, "new.ready");
      assertFalse(Files.exists(root.resolve("new.ready")));
      assertFailure(StorageIoException.Reason.MISSING, () -> calls.unlink(fd, "new.ready"));
      assertFailure(
          StorageIoException.Reason.MISSING, () -> calls.publish(fd, "missing", "another"));
      Files.createSymbolicLink(root.resolve("link"), root.resolve("20260908"));
      assertFailure(StorageIoException.Reason.UNAVAILABLE, () -> calls.openDirectory(fd, "link"));
      assertFailure(
          StorageIoException.Reason.UNAVAILABLE, () -> calls.openDirectory(fd, "sample.ready"));
      assertFailure(StorageIoException.Reason.UNAVAILABLE, () -> calls.sync(-1));
      assertFailure(StorageIoException.Reason.UNAVAILABLE, () -> calls.close(-1));
      assertFailure(StorageIoException.Reason.UNAVAILABLE, () -> calls.createDirectory(-1, "date"));
      assertFailure(StorageIoException.Reason.UNAVAILABLE, () -> calls.openDirectory(-1, "date"));
      assertFailure(
          StorageIoException.Reason.UNAVAILABLE, () -> calls.publish(-1, "part", "ready"));
      assertFailure(StorageIoException.Reason.UNAVAILABLE, () -> calls.unlink(-1, "part"));
    } finally {
      calls.close(fd);
    }
  }

  @Test
  void f01RejectsNullNamesTraversalUnknownAbiAndMissingSymbols() throws Exception {
    DirectoryCalls calls = LinuxDirectoryCalls.create();
    for (String name : List.of("", ".", "..", "a/b", "a\0b", "/")) {
      assertThrows(IllegalArgumentException.class, () -> calls.openDirectory(-1, name));
      assertThrows(IllegalArgumentException.class, () -> calls.openEntry(-1, name));
      assertThrows(IllegalArgumentException.class, () -> calls.createDirectory(-1, name));
      assertThrows(IllegalArgumentException.class, () -> calls.publish(-1, name, "ready"));
      assertThrows(IllegalArgumentException.class, () -> calls.publish(-1, "part", name));
      assertThrows(IllegalArgumentException.class, () -> calls.unlink(-1, name));
    }
    assertThrows(NullPointerException.class, () -> calls.openDirectory(-1, null));
    assertThrows(NullPointerException.class, () -> calls.openEntry(-1, null));
    assertFailure(StorageIoException.Reason.UNAVAILABLE, () -> calls.openEntry(-1, "entry"));
    assertThrows(NullPointerException.class, () -> calls.createDirectory(-1, null));
    assertThrows(NullPointerException.class, () -> calls.publish(-1, null, "ready"));
    assertThrows(NullPointerException.class, () -> calls.publish(-1, "part", null));
    assertThrows(NullPointerException.class, () -> calls.unlink(-1, null));
    assertThrows(NullPointerException.class, () -> new StorageIoException(null));
    SymbolLookup symbols = Linker.nativeLinker().defaultLookup();
    assertThrows(
        NullPointerException.class, () -> LinuxDirectoryCalls.create(null, "amd64", symbols));
    assertThrows(
        NullPointerException.class, () -> LinuxDirectoryCalls.create("Linux", null, symbols));
    assertThrows(
        NullPointerException.class, () -> LinuxDirectoryCalls.create("Linux", "amd64", null));
    assertThrows(
        IllegalStateException.class, () -> LinuxDirectoryCalls.create("Windows", "amd64", symbols));
    assertThrows(
        IllegalStateException.class, () -> LinuxDirectoryCalls.create("Linux", "unknown", symbols));
    assertEquals(
        "native storage is unavailable",
        assertThrows(
                IllegalStateException.class,
                () -> LinuxDirectoryCalls.create("Linux", "amd64", name -> Optional.empty()))
            .getMessage());
  }

  @Test
  void f03OneOf100ConcurrentPublishersWinsWithoutReplacingWinner() throws Exception {
    DirectoryCalls calls = LinuxDirectoryCalls.create();
    int fd = open(calls, root);
    try (var executor = Executors.newFixedThreadPool(16)) {
      List<Callable<Integer>> tasks = new ArrayList<>();
      for (int i = 0; i < 100; i++) {
        int id = i;
        Files.write(
            root.resolve(id + ".part"), new byte[] {(byte) id}, StandardOpenOption.CREATE_NEW);
        tasks.add(
            () -> {
              try {
                calls.publish(fd, id + ".part", "winner.ready");
                return id;
              } catch (StorageIoException ex) {
                assertEquals(StorageIoException.Reason.COLLISION, ex.reason());
                return -1;
              }
            });
      }
      int wins = 0;
      for (var future : executor.invokeAll(tasks)) {
        int id = future.get();
        if (id >= 0) {
          wins++;
          assertArrayEquals(
              new byte[] {(byte) id}, Files.readAllBytes(root.resolve("winner.ready")));
          assertFalse(Files.exists(root.resolve(id + ".part")));
        }
      }
      assertEquals(1, wins);
      byte winner = Files.readAllBytes(root.resolve("winner.ready"))[0];
      for (int i = 0; i < 100; i++) {
        if (i != winner)
          assertArrayEquals(new byte[] {(byte) i}, Files.readAllBytes(root.resolve(i + ".part")));
      }
      try (var entries = Files.list(root)) {
        assertEquals(100L, entries.count());
      }
    } finally {
      calls.close(fd);
    }
  }

  private static int open(DirectoryCalls calls, Path path) throws StorageIoException {
    int fd = calls.openRoot();
    for (Path component : path) {
      int child = calls.openDirectory(fd, component.toString());
      calls.close(fd);
      fd = child;
    }
    return fd;
  }

  private static void assertFailure(
      StorageIoException.Reason reason, org.junit.jupiter.api.function.Executable action) {
    StorageIoException ex = assertThrows(StorageIoException.class, action);
    assertEquals(reason, ex.reason());
    assertEquals("transfer storage operation failed", ex.getMessage());
    assertNull(ex.getCause());
    assertEquals(0, ex.getSuppressed().length);
  }
}

package dev.codex.schubert.nk.storage;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
