package dev.codex.schubert.nk.storage;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.lang.foreign.Linker;
import java.lang.foreign.ValueLayout;
import java.util.Optional;
import org.junit.jupiter.api.Test;

/** SSC119/289 COWNER: independently specified CLOCK_MONOTONIC timespec and overflow vectors. */
class LinuxMonotonicClockTest {
  @Test
  void literalTimespecAndExactSignedLongBoundary() throws Exception {
    assertEquals(0L, clock(0, 0).nowNanos());
    assertEquals(2_999_999_999L, clock(2, 999_999_999).nowNanos());
    assertEquals(9_223_372_036_854_775_807L, clock(9_223_372_036L, 854_775_807).nowNanos());
  }

  @Test
  void negativeAndOverflowNeverWrapOrUseAnotherClock() {
    for (long[] pair :
        new long[][] {
          {-1, 0}, {0, -1}, {0, 1_000_000_000L}, {9_223_372_036L, 854_775_808}, {9_223_372_037L, 0}
        }) {
      var failure = assertThrows(IOException.class, () -> clock(pair[0], pair[1]).nowNanos());
      assertEquals("shared monotonic clock unavailable", failure.getMessage());
      assertNull(failure.getCause());
    }
    var failed = new LinuxMonotonicClock((id, result) -> -1);
    assertThrows(IOException.class, failed::nowNanos);
    assertThrows(NullPointerException.class, () -> new LinuxMonotonicClock(null));
  }

  @Test
  void fixedAbiPlatformAndSymbolFailures() throws Exception {
    var symbols = Linker.nativeLinker().defaultLookup();
    assertThrows(
        NullPointerException.class, () -> LinuxMonotonicClock.create(null, "amd64", symbols));
    assertThrows(
        NullPointerException.class, () -> LinuxMonotonicClock.create("Linux", null, symbols));
    assertThrows(
        NullPointerException.class, () -> LinuxMonotonicClock.create("Linux", "amd64", null));
    assertThrows(
        IllegalStateException.class, () -> LinuxMonotonicClock.create("Windows", "amd64", symbols));
    assertThrows(
        IllegalStateException.class, () -> LinuxMonotonicClock.create("Linux", "unknown", symbols));
    assertThrows(
        IllegalStateException.class,
        () -> LinuxMonotonicClock.create("Linux", "amd64", name -> Optional.empty()));
    for (String architecture : new String[] {"amd64", "x86_64", "aarch64"}) {
      long time = LinuxMonotonicClock.create("Linux", architecture, symbols).nowNanos();
      assertTrue(time > 0, "host uptime must be a positive monotonic observation");
    }
    var actual = LinuxMonotonicClock.create();
    long before = actual.nowNanos();
    long after = actual.nowNanos();
    assertTrue(after >= before, "CLOCK_MONOTONIC must never move backward within this boot");
  }

  private static LinuxMonotonicClock clock(long seconds, long nanos) {
    return new LinuxMonotonicClock(
        (id, result) -> {
          assertEquals(1, id, "only Linux CLOCK_MONOTONIC is selected");
          assertEquals(16, result.byteSize());
          result.set(ValueLayout.JAVA_LONG, 0, seconds);
          result.set(ValueLayout.JAVA_LONG, 8, nanos);
          return 0;
        });
  }
}

package dev.codex.schubert.nk.storage;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.lang.foreign.Linker;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.ValueLayout;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.Callable;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;

/** Independent literal pointer vectors/native same PID oracle; SS342/343; SSC086. */
final class LinuxProcessExecTest {
  private static final Path HELD = Path.of("/proc/self/fd/17");

  @Test
  void opsExec001LiteralVectorsAndArenaLifetime() {
    var captures = new ArrayList<MemorySegment>();
    var replacement =
        new LinuxProcessExec(
            (file, argv, env) -> {
              assertEquals("/proc/self/fd/17", file.getString(0));
              assertEquals(List.of("setpriv", "--no-new-privs", "日本語", ""), strings(argv));
              assertEquals(
                  List.of(
                      "CREDENTIALS_DIRECTORY=/run/credentials/unit",
                      "INVOCATION_ID=public_fixture"),
                  strings(env));
              captures.add(file);
              captures.add(argv);
              captures.add(env);
              return -1;
            });
    unavailable(
        assertThrows(
            StorageIoException.class,
            () ->
                replacement.replace(
                    HELD,
                    List.of("setpriv", "--no-new-privs", "日本語", ""),
                    Map.of(
                        "INVOCATION_ID",
                        "public_fixture",
                        "CREDENTIALS_DIRECTORY",
                        "/run/credentials/unit"))));
    assertEquals(3, captures.size());
    for (var segment : captures) assertFalse(segment.scope().isAlive());
  }

  @Test
  void opsExec002EveryNativeReturnIsRedactedFailure() {
    for (int returned : List.of(-1, 0, 1, Integer.MIN_VALUE, Integer.MAX_VALUE)) {
      var calls = new AtomicInteger();
      var replacement =
          new LinuxProcessExec(
              (file, argv, env) -> {
                assertEquals(List.of("java"), strings(argv));
                assertEquals(List.of(), strings(env));
                calls.incrementAndGet();
                return returned;
              });
      unavailable(
          assertThrows(
              StorageIoException.class,
              () -> replacement.replace(HELD, List.of("java"), Map.of())));
      assertEquals(1, calls.get());
    }
    // Real execve ENOENT, never a raw native diagnostic.
    unavailable(
        assertThrows(
            StorageIoException.class,
            () ->
                LinuxProcessExec.create()
                    .replace(Path.of("/proc/self/fd/2147483647"), List.of("java"), Map.of())));
  }

  @Test
  void opsExec003InputNullAndPathContracts() {
    var calls = new AtomicInteger();
    var replacement = new LinuxProcessExec((p, a, e) -> calls.incrementAndGet());
    for (String path :
        List.of(
            "/tmp/exec",
            "/proc/1/fd/17",
            "/proc/self/fd/-1",
            "/proc/self/fd/+1",
            "/proc/self/fd/01",
            "/proc/self/fd/99999999999",
            "/proc/self/fd/2147483648",
            "/proc/self/fd/17/child"))
      invalid(
          assertThrows(
              IllegalArgumentException.class,
              () -> replacement.replace(Path.of(path), List.of("java"), Map.of())));
    assertThrows(
        NullPointerException.class, () -> replacement.replace(null, List.of("java"), Map.of()));
    assertThrows(NullPointerException.class, () -> replacement.replace(HELD, null, Map.of()));
    assertThrows(
        NullPointerException.class, () -> replacement.replace(HELD, List.of("java"), null));
    assertThrows(
        NullPointerException.class,
        () -> replacement.replace(HELD, Arrays.asList("java", null), Map.of()));
    var bad = new HashMap<String, String>();
    bad.put(null, "x");
    assertThrows(NullPointerException.class, () -> replacement.replace(HELD, List.of("java"), bad));
    bad.clear();
    bad.put("X", null);
    assertThrows(NullPointerException.class, () -> replacement.replace(HELD, List.of("java"), bad));
    assertThrows(NullPointerException.class, () -> new LinuxProcessExec(null));
    assertEquals(0, calls.get());
  }

  @Test
  void opsExec004VectorAndStringBoundaries() {
    var calls = new AtomicInteger();
    var replacement =
        new LinuxProcessExec(
            (p, a, e) -> {
              calls.incrementAndGet();
              return -1;
            });
    invalid(
        assertThrows(
            IllegalArgumentException.class, () -> replacement.replace(HELD, List.of(), Map.of())));
    invalid(
        assertThrows(
            IllegalArgumentException.class,
            () -> replacement.replace(HELD, Collections.nCopies(65, "x"), Map.of())));
    var env = new HashMap<String, String>();
    for (int i = 0; i < 33; i++) env.put("X" + i, "");
    invalid(
        assertThrows(
            IllegalArgumentException.class, () -> replacement.replace(HELD, List.of("x"), env)));
    env.remove("X32");
    unavailable(
        assertThrows(
            StorageIoException.class,
            () -> replacement.replace(HELD, Collections.nCopies(64, "x"), env)));
    unavailable(
        assertThrows(
            StorageIoException.class,
            () ->
                replacement.replace(
                    Path.of("/proc/self/fd/0"),
                    List.of("x".repeat(4096)),
                    Map.of("A".repeat(64), "x".repeat(4096)))));
    for (String value : List.of("x".repeat(4097), "\0", "\n", "\r", "\t", "\u007f")) {
      invalid(
          assertThrows(
              IllegalArgumentException.class,
              () -> replacement.replace(HELD, List.of(value), Map.of())));
      invalid(
          assertThrows(
              IllegalArgumentException.class,
              () -> replacement.replace(HELD, List.of("x"), Map.of("A", value))));
    }
    for (String key : List.of("", "a", "0A", "A=B", "A\n", "A".repeat(65)))
      invalid(
          assertThrows(
              IllegalArgumentException.class,
              () -> replacement.replace(HELD, List.of("x"), Map.of(key, ""))));
    assertEquals(2, calls.get());
  }

  @Test
  void opsExec005PlatformAndSymbolContracts() {
    var symbols = Linker.nativeLinker().defaultLookup();
    assertThrows(NullPointerException.class, () -> LinuxProcessExec.create(null, "amd64", symbols));
    assertThrows(NullPointerException.class, () -> LinuxProcessExec.create("Linux", null, symbols));
    assertThrows(NullPointerException.class, () -> LinuxProcessExec.create("Linux", "amd64", null));
    for (String os : List.of("Windows", "linux", ""))
      assertThrows(
          IllegalStateException.class, () -> LinuxProcessExec.create(os, "amd64", symbols));
    assertThrows(
        IllegalStateException.class, () -> LinuxProcessExec.create("Linux", "unknown", symbols));
    assertThrows(
        IllegalStateException.class,
        () -> LinuxProcessExec.create("Linux", "amd64", name -> Optional.empty()));
    for (String arch : List.of("amd64", "x86_64", "aarch64"))
      assertNotNull(LinuxProcessExec.create("Linux", arch, symbols));
  }

  @Test
  void opsExec006UnknownFailureIdentityAndArenaClose() {
    for (Throwable unknown :
        List.of(
            new IllegalStateException("public unknown"), new AssertionError("public unknown"))) {
      var captures = new ArrayList<MemorySegment>();
      var replacement =
          new LinuxProcessExec(
              (p, a, e) -> {
                captures.add(a);
                if (unknown instanceof RuntimeException runtime) throw runtime;
                throw (Error) unknown;
              });
      assertSame(
          unknown,
          assertThrows(
              unknown.getClass(), () -> replacement.replace(HELD, List.of("x"), Map.of())));
      assertFalse(captures.getFirst().scope().isAlive());
      assertEquals(0, unknown.getSuppressed().length);
    }
  }

  @Test
  void opsExec007ConcurrentInputsRemainIndependent() throws Exception {
    var calls = new AtomicInteger();
    var expectedInput = new ThreadLocal<String>();
    var replacement =
        new LinuxProcessExec(
            (p, a, e) -> {
              String expected = expectedInput.get();
              assertNotNull(expected, "independent task fixture must be bound");
              assertEquals(List.of(expected), strings(a));
              assertEquals(List.of("X=" + expected), strings(e));
              calls.incrementAndGet();
              return -1;
            });
    try (var executor = Executors.newFixedThreadPool(8)) {
      var work = new ArrayList<Callable<Boolean>>();
      for (int i = 0; i < 32; i++) {
        String value = "fixture" + i;
        work.add(
            () -> {
              expectedInput.set(value);
              try {
                unavailable(
                    assertThrows(
                        StorageIoException.class,
                        () -> replacement.replace(HELD, List.of(value), Map.of("X", value))));
                return true;
              } finally {
                expectedInput.remove();
              }
            });
      }
      for (var result : executor.invokeAll(work)) assertTrue(result.get(5, TimeUnit.SECONDS));
    }
    assertEquals(32, calls.get());
  }

  @Test
  void opsExec008ActualReplacementKeepsPidAndOnlyPreparedEnvironment() throws Exception {
    var builder =
        new ProcessBuilder(
                Path.of(System.getProperty("java.home"), "bin/java").toString(),
                "--enable-native-access=ALL-UNNAMED",
                "-cp",
                System.getProperty("java.class.path"),
                LinuxProcessExecChild.class.getName())
            .redirectErrorStream(true);
    builder.environment().put("PGPT_EXEC_UNEXPECTED", "public_fixture");
    var child = builder.start();
    try {
      assertTrue(child.waitFor(10, TimeUnit.SECONDS));
      assertEquals(0, child.exitValue());
      assertEquals(
          "PID=" + child.pid() + " ENV=fixture_only\n", child.inputReader().readLine() + "\n");
      assertEquals(-1, child.getInputStream().read());
    } finally {
      if (child.isAlive()) child.destroy();
    }
  }

  // Every pointed string is freshly allocated by the tested confined arena; bounded fixture only.
  @SuppressWarnings("restricted")
  private static List<String> strings(MemorySegment vector) {
    var result = new ArrayList<String>();
    for (int index = 0; ; index++) {
      var pointer = vector.getAtIndex(ValueLayout.ADDRESS, index);
      if (pointer.equals(MemorySegment.NULL)) return result;
      result.add(pointer.reinterpret(8192).getString(0));
    }
  }

  private static void unavailable(StorageIoException failure) {
    assertEquals(StorageIoException.Reason.UNAVAILABLE, failure.reason());
    assertEquals("transfer storage operation failed", failure.getMessage());
    assertNull(failure.getCause());
    assertEquals(0, failure.getSuppressed().length);
  }

  private static void invalid(IllegalArgumentException failure) {
    assertEquals("invalid process replacement input", failure.getMessage());
    assertNull(failure.getCause());
  }
}

package dev.codex.schubert.nk.storage;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.lang.foreign.Linker;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.ValueLayout;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.Callable;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import org.junit.jupiter.api.Test;

/** PT-OPS-SEAL-001..008; independent public byte vectors and actual immutable Linux memfd. */
final class LinuxSealedProofTest {
  private static final byte[] VECTOR =
      "NKSTART1\npublic_fixture\n".getBytes(StandardCharsets.US_ASCII);

  @Test
  void opsSeal001LiteralBytesFlagsOrderAndScopedClose() throws Exception {
    var f = new Fixture(VECTOR);
    byte[] input = VECTOR.clone();
    assertEquals(
        "observed",
        f.calls()
            .withProof(
                input,
                fd -> {
                  assertEquals(129, fd);
                  f.events.add("body");
                  assertArrayEquals(VECTOR, f.written.toByteArray());
                  assertArrayEquals(VECTOR, f.calls().read(fd));
                  return "observed";
                }));
    assertArrayEquals(VECTOR, input);
    assertEquals(
        List.of(
            "create",
            "mode:17:384",
            "write:17",
            "fcntl:17:1033:15",
            "fcntl:17:1030:128",
            "body",
            "fcntl:129:1034:0",
            "read:129:0",
            "read:129:24",
            "close:129",
            "close:17"),
        f.events);
  }

  @Test
  void opsSeal002AllCreationSyscallFailuresAndCleanup() {
    for (String failed :
        List.of("create", "mode", "write", "seal", "duplicate", "closeReserved", "closeOriginal")) {
      var f = new Fixture(VECTOR);
      f.failed = failed;
      unavailable(
          assertThrows(
              StorageIoException.class,
              () ->
                  f.calls()
                      .withProof(
                          VECTOR,
                          fd -> {
                            f.events.add("body");
                            return true;
                          })));
      if (!failed.equals("create")) assertEquals("close:17", f.events.getLast());
      if (List.of("closeReserved", "closeOriginal").contains(failed))
        assertTrue(f.events.contains("body"));
      else assertFalse(f.events.contains("body"));
    }
    for (long count : List.of(0L, -1L, (long) VECTOR.length + 1)) {
      var f = new Fixture(VECTOR);
      f.writeResult = count;
      unavailable(
          assertThrows(StorageIoException.class, () -> f.calls().withProof(VECTOR, fd -> fail())));
      assertEquals("close:17", f.events.getLast());
    }
    for (int reserved : List.of(127, 65536)) {
      var f = new Fixture(VECTOR);
      f.reserved = reserved;
      unavailable(
          assertThrows(StorageIoException.class, () -> f.calls().withProof(VECTOR, fd -> fail())));
      assertEquals(
          List.of("close:" + reserved, "close:17"),
          f.events.subList(f.events.size() - 2, f.events.size()));
    }
  }

  @Test
  void opsSeal003ReadSealEmptyOversizeAndNativeErrors() {
    for (int seal : List.of(-1, 0, 1, 7, 14, 31)) {
      var f = new Fixture(VECTOR);
      f.seals = seal;
      unavailable(assertThrows(StorageIoException.class, () -> f.calls().read(129)));
      assertEquals(List.of("fcntl:129:1034:0"), f.events);
    }
    for (byte[] bytes : List.of(new byte[0], new byte[8193])) {
      var f = new Fixture(bytes);
      unavailable(assertThrows(StorageIoException.class, () -> f.calls().read(129)));
      assertFalse(f.events.stream().anyMatch(event -> event.startsWith("close:")));
    }
    for (long result : List.of(-1L, 8194L)) {
      var f = new Fixture(VECTOR);
      f.readResult = result;
      unavailable(assertThrows(StorageIoException.class, () -> f.calls().read(129)));
    }
    unavailable(
        assertThrows(StorageIoException.class, () -> LinuxSealedProof.create().read(65535)));
  }

  @Test
  void opsSeal004BoundaryAndPartialIoIndependentVector() throws Exception {
    for (int size : List.of(1, 8192)) {
      byte[] vector = new byte[size];
      Arrays.fill(vector, (byte) 'a');
      var f = new Fixture(vector);
      f.chunk = 3;
      assertArrayEquals(vector, f.calls().withProof(vector, fd -> f.calls().read(fd)));
      assertArrayEquals(vector, f.written.toByteArray());
      assertEquals("close:17", f.events.getLast());
    }
    var f = new Fixture(VECTOR);
    f.reserved = 65535;
    boolean boundary =
        f.calls()
            .withProof(
                VECTOR,
                fd -> {
                  assertEquals(65535, fd);
                  return true;
                });
    assertTrue(boundary);
  }

  @Test
  void opsSeal005NullAndPlatformContracts() {
    var f = new Fixture(VECTOR);
    var calls = f.calls();
    assertThrows(NullPointerException.class, () -> calls.withProof(null, fd -> true));
    assertThrows(NullPointerException.class, () -> calls.withProof(VECTOR, null));
    for (byte[] bytes : List.of(new byte[0], new byte[8193]))
      assertThrows(IllegalArgumentException.class, () -> calls.withProof(bytes, fd -> true));
    for (int fd : List.of(127, 65536))
      assertThrows(IllegalArgumentException.class, () -> calls.read(fd));
    assertTrue(f.events.isEmpty());
    var symbols = Linker.nativeLinker().defaultLookup();
    assertThrows(NullPointerException.class, () -> LinuxSealedProof.create(null, "amd64", symbols));
    assertThrows(NullPointerException.class, () -> LinuxSealedProof.create("Linux", null, symbols));
    assertThrows(NullPointerException.class, () -> LinuxSealedProof.create("Linux", "amd64", null));
    for (String os : List.of("Windows", "linux", ""))
      assertThrows(
          IllegalStateException.class, () -> LinuxSealedProof.create(os, "amd64", symbols));
    assertThrows(
        IllegalStateException.class, () -> LinuxSealedProof.create("Linux", "unknown", symbols));
    for (String missing : List.of("memfd_create", "write", "pread", "fcntl", "fchmod", "close"))
      assertThrows(
          IllegalStateException.class,
          () ->
              LinuxSealedProof.create(
                  "Linux",
                  "amd64",
                  name -> name.equals(missing) ? Optional.empty() : symbols.find(name)));
    for (String arch : List.of("amd64", "x86_64", "aarch64"))
      assertNotNull(LinuxSealedProof.create("Linux", arch, symbols));
    LinuxSealedProof.CreateCall create = (n, flags) -> 17;
    LinuxSealedProof.WriteCall write = (d, b, n) -> n;
    LinuxSealedProof.ReadCall read = (d, b, n, o) -> 0;
    LinuxSealedProof.FcntlCall fcntl = (d, c, a) -> 0;
    LinuxSealedProof.ModeCall mode = (d, m) -> 0;
    LinuxSealedProof.CloseCall close = d -> 0;
    assertThrows(
        NullPointerException.class,
        () -> new LinuxSealedProof(null, write, read, fcntl, mode, close));
    assertThrows(
        NullPointerException.class,
        () -> new LinuxSealedProof(create, null, read, fcntl, mode, close));
    assertThrows(
        NullPointerException.class,
        () -> new LinuxSealedProof(create, write, null, fcntl, mode, close));
    assertThrows(
        NullPointerException.class,
        () -> new LinuxSealedProof(create, write, read, null, mode, close));
    assertThrows(
        NullPointerException.class,
        () -> new LinuxSealedProof(create, write, read, fcntl, null, close));
    assertThrows(
        NullPointerException.class,
        () -> new LinuxSealedProof(create, write, read, fcntl, mode, null));
  }

  @Test
  void opsSeal006UnknownCompoundAndAllOwnedClose() {
    for (boolean cleanupUnknown : List.of(false, true))
      for (boolean knownBody : List.of(false, true))
        for (Throwable unknown :
            List.of(
                new IllegalStateException("public unknown"),
                new AssertionError("public unknown"))) {
          var f = new Fixture(VECTOR);
          f.cleanupUnknown = cleanupUnknown ? unknown : null;
          Class<? extends Throwable> expectedType =
              knownBody && !cleanupUnknown ? StorageIoException.class : unknown.getClass();
          var actual =
              assertThrows(
                  expectedType,
                  () ->
                      f.calls()
                          .withProof(
                              VECTOR,
                              fd -> {
                                if (knownBody) throw new IOException("private fixture diagnostic");
                                if (unknown instanceof RuntimeException failure) throw failure;
                                throw (Error) unknown;
                              }));
          if (knownBody && !cleanupUnknown) unavailable((StorageIoException) actual);
          else assertSame(unknown, actual);
          assertEquals(
              List.of("close:129", "close:17"),
              f.events.subList(f.events.size() - 2, f.events.size()));
        }
  }

  @Test
  void opsSeal007RealMemfdModeSealsAndMutationRefusal() throws Exception {
    var proof = LinuxSealedProof.create();
    var saved = new int[] {-1};
    assertEquals(
        "verified",
        proof.withProof(
            VECTOR,
            fd -> {
              saved[0] = fd;
              var path = Path.of("/proc/self/fd/" + fd);
              var metadata = Files.readAttributes(path, "unix:mode,nlink,size");
              assertEquals(0100600, metadata.get("mode"));
              assertEquals(0, metadata.get("nlink"));
              assertEquals((long) VECTOR.length, metadata.get("size"));
              assertArrayEquals(VECTOR, proof.read(fd));
              assertThrows(IOException.class, () -> Files.write(path, new byte[] {1}));
              try (var channel = Files.newByteChannel(path, StandardOpenOption.WRITE)) {
                assertThrows(IOException.class, () -> channel.truncate(1));
                assertThrows(
                    IOException.class,
                    () -> channel.write(java.nio.ByteBuffer.wrap(new byte[] {1})));
                channel.position(VECTOR.length);
                assertThrows(
                    IOException.class,
                    () -> channel.write(java.nio.ByteBuffer.wrap(new byte[] {1})));
              }
              assertArrayEquals(VECTOR, proof.read(fd));
              return "verified";
            }));
    unavailable(assertThrows(StorageIoException.class, () -> proof.read(saved[0])));
  }

  @Test
  void opsSeal008NativeConcurrentProofsNeverMix() throws Exception {
    var proof = LinuxSealedProof.create();
    try (var executor = Executors.newFixedThreadPool(8)) {
      var work = new ArrayList<Callable<Boolean>>();
      for (int i = 0; i < 32; i++) {
        byte[] literal = ("PUBLIC-" + i).getBytes(StandardCharsets.US_ASCII);
        work.add(
            () ->
                proof.withProof(
                    literal,
                    fd -> {
                      assertArrayEquals(literal, proof.read(fd));
                      return true;
                    }));
      }
      for (var result : executor.invokeAll(work)) assertTrue(result.get(10, TimeUnit.SECONDS));
    }
  }

  private static void unavailable(StorageIoException failure) {
    assertEquals(StorageIoException.Reason.UNAVAILABLE, failure.reason());
    assertEquals("transfer storage operation failed", failure.getMessage());
    assertNull(failure.getCause());
    assertEquals(0, failure.getSuppressed().length);
  }

  private static final class Fixture {
    final byte[] vector;
    final List<String> events = new ArrayList<>();
    final ByteArrayOutputStream written = new ByteArrayOutputStream();
    String failed = "";
    long writeResult = Long.MIN_VALUE;
    long readResult = Long.MIN_VALUE;
    int seals = 15;
    int reserved = 129;
    int chunk = 8193;
    Throwable cleanupUnknown;

    Fixture(byte[] vector) {
      this.vector = vector.clone();
    }

    LinuxSealedProof calls() {
      return new LinuxSealedProof(
          (name, flags) -> {
            assertEquals("schubert-startup-proof", name.getString(0));
            assertEquals(3, flags);
            events.add("create");
            return failed.equals("create") ? -1 : 17;
          },
          (fd, buffer, count) -> {
            events.add("write:" + fd);
            if (failed.equals("write")) return -1;
            if (writeResult != Long.MIN_VALUE) return writeResult;
            int n = (int) Math.min(count, chunk);
            written.writeBytes(buffer.asSlice(0, n).toArray(ValueLayout.JAVA_BYTE));
            return n;
          },
          (fd, buffer, count, offset) -> {
            events.add("read:" + fd + ":" + offset);
            if (readResult != Long.MIN_VALUE) return readResult;
            int n = (int) Math.min(Math.min(count, chunk), vector.length - offset);
            MemorySegment.copy(vector, (int) offset, buffer, ValueLayout.JAVA_BYTE, 0, n);
            return n;
          },
          (fd, cmd, arg) -> {
            events.add("fcntl:" + fd + ":" + cmd + ":" + arg);
            return switch (cmd) {
              case 1033 -> failed.equals("seal") ? -1 : 0;
              case 1030 -> failed.equals("duplicate") ? -1 : reserved;
              case 1034 -> seals;
              default -> throw new AssertionError("unknown fixture command");
            };
          },
          (fd, permissions) -> {
            events.add("mode:" + fd + ":" + permissions);
            return failed.equals("mode") ? -1 : 0;
          },
          fd -> {
            events.add("close:" + fd);
            if (fd == 129 && cleanupUnknown != null) {
              if (cleanupUnknown instanceof RuntimeException failure) throw failure;
              throw (Error) cleanupUnknown;
            }
            return (fd == 129 && failed.equals("closeReserved"))
                    || (fd == 17 && failed.equals("closeOriginal"))
                ? -1
                : 0;
          });
    }
  }
}

package dev.codex.schubert.nk.storage;

