  @Test
  void childfd006UnknownAndCompoundFailurePriorityAndOneClose() {
    for (int fd : List.of(A, P))
      for (Throwable unknown :
          List.of(new AssertionError("PRIVATE"), new IllegalStateException("PRIVATE"))) {
        var f = new Fixture();
        f.failClose = fd;
        f.unknown = unknown;
        assertSame(
            unknown,
            assertThrows(unknown.getClass(), () -> f.subject().withAdmitted(A, P, (a, p) -> 1)));
        assertEquals(List.of(P, A), f.closed);
        assertArrayEquals(new byte[3], f.payload);
      }
    for (int closeFd : List.of(0, A)) {
      var f = new Fixture();
      f.failClose = closeFd;
      var primary = new AssertionError("PRIMARY");
      assertSame(
          primary,
          assertThrows(
              AssertionError.class,
              () ->
                  f.subject()
                      .withAdmitted(
                          A,
                          P,
                          (a, p) -> {
                            throw primary;
                          })));
      assertEquals(List.of(P, A), f.closed);
    }
    var f = new Fixture();
    f.failClose = A;
    var fatal = new AssertionError("PRIVATE");
