    try (var child = parent.openExistingChild("音楽 folder")) {
      parent.close();
      assertEquals(1, calls.live.size());
      Path retained = root.resolve("retained");
      Files.move(directory, retained);
      Files.createSymbolicLink(directory, outside);
      assertArrayEquals(
          new byte[] {1, 2, 3},
