import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.fail;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import org.apache.catalina.LifecycleException;
import org.junit.jupiter.api.Test;

/** SS313342352/PG-D378/WEB-REM004: independent control order and original failure identity. */
final class WebRuntimeExecutionTest {
  @Test
  void rem004NormalAndEveryStartOrAwaitFailureStopsAndClosesOnce() throws Exception {
    for (int phase : new int[] {-1, 0, 1}) {
      for (Throwable primary :
          List.of(
              new IOException("synthetic"),
              new IllegalStateException("synthetic"),
              new AssertionError("synthetic"))) {
        var events = new ArrayList<String>();
        var start =
            (WebRuntimeExecution.Start)
                () -> {
                  events.add("start");
                  if (phase == 0) raise(primary);
                };
        var await =
            (WebRuntimeExecution.Io)
                () -> {
                  events.add("await");
                  if (phase == 1) raise(primary);
                };
        if (phase == -1)
          WebRuntimeExecution.execute(
              start, await, () -> events.add("stop"), () -> events.add("close"));
        else
          assertSame(
              primary,
              assertThrows(
                  primary.getClass(),
                  () ->
                      WebRuntimeExecution.execute(
                          start, await, () -> events.add("stop"), () -> events.add("close"))));
        assertEquals(
            phase == 0
                ? List.of("start", "stop", "close")
                : List.of("start", "await", "stop", "close"),
            events);
      }
    }
    var events = new ArrayList<String>();
    IOException converted =
        assertThrows(
            IOException.class,
            () ->
                WebRuntimeExecution.execute(
                    () -> {
                      events.add("start");
                      throw new LifecycleException("synthetic private");
                    },
                    () -> fail("failed startup must not await"),
                    () -> events.add("stop"),
                    () -> events.add("close")));
    assertEquals("Web HTTP startup unavailable", converted.getMessage());
    assertNull(converted.getCause());
    assertEquals(0, converted.getSuppressed().length);
    assertEquals(List.of("start", "stop", "close"), events);
  }

  @Test
  void rem004InvariantsRejectAbsentCallbacksBeforeFirstAction() {
    WebRuntimeExecution.Start start = () -> fail("invalid callbacks must not start");
    WebRuntimeExecution.Io io = () -> fail("invalid callbacks must not borrow");
    Runnable stop = () -> fail("invalid callbacks must not stop");
    assertThrows(NullPointerException.class, () -> WebRuntimeExecution.execute(null, io, stop, io));
    assertThrows(
        NullPointerException.class, () -> WebRuntimeExecution.execute(start, null, stop, io));
    assertThrows(
        NullPointerException.class, () -> WebRuntimeExecution.execute(start, io, null, io));
    assertThrows(
        NullPointerException.class, () -> WebRuntimeExecution.execute(start, io, stop, null));
  }

  private static void raise(Throwable failure) throws IOException {
    if (failure instanceof IOException io) throw io;
    if (failure instanceof RuntimeException runtime) throw runtime;
    throw (Error) failure;
  }
}

package dev.codex.schubert.nk.web.bootstrap;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.io.IOException;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.jupiter.api.Test;

/** SS342352 / PT-OPS-NWEB-STOP001..005. Independent literal 30s/phase/UNKNOWN oracle. */
final class WebRuntimeStopTest {
  @Test
  void stop001NormalPhaseOrderAndRepeatedCloseNeverReleaseTwice() throws Exception {
    var clock = new AtomicLong(1_000_000_000L);
    var owner = new WebRuntimeStop(clock::get);
    owner.begin();
    var calls = new ArrayList<String>();
    WebRuntimeStop.Step[] steps = {
      left -> {
        assertEquals(Duration.ofSeconds(30), left);
        calls.add("HTTP");
        clock.addAndGet(2_000_000_000L);
      },
      left -> {
        assertEquals(Duration.ofSeconds(28), left);
        calls.add("worker");
      },
      left -> {
        assertEquals(Duration.ofSeconds(28), left);
        calls.add("broker");
      }
    };
    owner.close(steps);
    clock.set(80_000_000_000L);
    owner.close(steps);
    assertEquals(List.of("HTTP", "worker", "broker"), calls);
    assertThrows(NullPointerException.class, () -> new WebRuntimeStop(null));
  }

  @Test
  void stop002UnknownPhaseRetainsLaterResourcesAndRetryUsesOriginalDeadline() throws Exception {
    var clock = new AtomicLong(0);
    var owner = new WebRuntimeStop(clock::get);
    owner.begin();
    var calls = new ArrayList<String>();
    WebRuntimeStop.Step[] failed = {
      left -> calls.add("HTTP"),
      left -> {
        calls.add("worker-unknown");
        throw new IOException("private detail");
      },
      left -> {
        throw new AssertionError("later broker must remain owned");
      }
    };
    var failure = assertThrows(IOException.class, () -> owner.close(failed));
    assertEquals("Web stop unconfirmed", failure.getMessage());
    assertNull(failure.getCause());
    assertEquals(0, failure.getSuppressed().length);
    clock.set(5_000_000_000L);
    owner.close(
        new WebRuntimeStop.Step[] {
          left -> {
            throw new AssertionError("confirmed HTTP must not close again");
          },
          left -> {
            assertEquals(Duration.ofSeconds(25), left);
            calls.add("worker-confirmed");
          },
          left -> {
            assertEquals(Duration.ofSeconds(25), left);
            calls.add("broker");
          }
        });
    assertEquals(List.of("HTTP", "worker-unknown", "worker-confirmed", "broker"), calls);
  }

  @Test
  void stop003DeadlineBoundaryDoesNotExtendAndExpiredRemainingIsZero() throws Exception {
    var clock = new AtomicLong(0);
    var owner = new WebRuntimeStop(clock::get);
    owner.begin();
    clock.set(30_000_000_000L);
    owner.close(new WebRuntimeStop.Step[] {left -> assertEquals(Duration.ZERO, left)});
    var expired = new WebRuntimeStop(clock::get);
    expired.begin();
    clock.set(60_000_000_001L);
    var error =
        assertThrows(
            IOException.class,
            () ->
                expired.close(
                    new WebRuntimeStop.Step[] {
                      left -> assertEquals(Duration.ZERO, left),
                      left -> {
                        throw new AssertionError("deadline exhausted before next phase");
                      }
                    }));
    assertEquals("Web stop unconfirmed", error.getMessage());
    assertNull(error.getCause());
  }

  @Test
  void stop004LifecycleAndRuntimeFailuresRemainFixedAndDoNotAdvance() {
    for (boolean lifecycle : new boolean[] {false, true}) {
      var owner = new WebRuntimeStop(() -> 0);
      owner.begin();
      var calls = new AtomicLong();
      WebRuntimeStop.Step[] steps = {
        left -> {
          calls.incrementAndGet();
          if (lifecycle) throw new org.apache.catalina.LifecycleException("private lifecycle");
          throw new IllegalStateException("private provider");
        }
      };
      for (int attempt = 0; attempt < 2; attempt++) {
        var failure = assertThrows(IOException.class, () -> owner.close(steps));
        assertEquals("Web stop unconfirmed", failure.getMessage());
        assertNull(failure.getCause());
      }
      assertEquals(2, calls.get());
    }
  }

  @Test
  void stop005FatalIdentityDirectAndNestedNeverTurnsIntoNormalStop() {
    var fatal = new AssertionError("synthetic fatal");
    for (boolean nested : new boolean[] {false, true}) {
      var owner = new WebRuntimeStop(() -> 0);
      owner.begin();
      assertSame(
          fatal,
          assertThrows(
              AssertionError.class,
              () ->
                  owner.close(
                      new WebRuntimeStop.Step[] {
                        left -> {
                          if (nested) throw new IOException("synthetic provider", fatal);
                          throw fatal;
                        },
                        left -> {
                          throw new AssertionError("fatal keeps later resource held");
                        }
                      })));
    }
  }
}

