final class LocalAuditGraph331Test {
  @Test
  void local331001LoggerGraphSignalsOnceBeforeOriginalFatalWithoutAnyProjection() {
    for (int edge = 0; edge < 4; edge++) {
      for (boolean duringCheck : new boolean[] {false, true}) {
