        new ArtemisRequestSender(
            () ->
                context(
                    Map.of(
                        "getSessionMode",
                        JMSContext.SESSION_TRANSACTED,
                        "createBytesMessage",
                        failingMessage,
                        "rollback",
                        checkedRollback)));
    assertEquals(
        checked, assertThrows(JMSException.class, () -> checkedSender.send(MESSAGE_ID, request)));
