      assertTrue(p.hits.get() > 0, fault);
      assertEquals(0, p.live.get(), fault);
      assertEquals(0, p.commits.get(), fault);
    }
    for (String fault :
        List.of(
            "getConnectionUnknown",
            "executeQueryUnknown",
