        case "0106" -> {
          var failure =
              assertThrows(
                  MqLoginLockedException.class, () -> fixture.provider.authenticate(input));
          fixed(failure, "login temporarily locked");
          assertEquals(900, failure.retryAfterSeconds());
        }
        default ->
            fixed(
                assertThrows(
